/// Outbound client messages: BiDi request body stream, or HTTP/1 BidiAppend.
#[derive(Clone)]
enum ClientOutbound {
    Bidi(mpsc::Sender<Result<Bytes, std::io::Error>>),
    Http1(BidiAppendSession),
}

/// A bounded channel send can time out while the request-body pump is briefly
/// backpressured. Tokio guarantees that cancelling `Sender::send` does not
/// enqueue the item, so retrying the exact same frame is safe for BiDi. Unary
/// HTTP/1 BidiAppend has an ambiguous acceptance boundary and remains
/// single-attempt regardless of these settings.
const DEFAULT_BIDI_SEND_RETRIES: u64 = 2;
const MAX_BIDI_SEND_RETRIES: u64 = 4;
const DEFAULT_BIDI_SEND_RETRY_BACKOFF_MS: u64 = 100;
const MAX_BIDI_SEND_RETRY_BACKOFF_MS: u64 = 2_000;

pub(crate) fn ambiguous_http1_append_error(error: CursorError, operation: &str) -> CursorError {
    if is_pre_connect_failure(&error) {
        return error;
    }
    // A deterministic Cursor KV quota response means this particular append
    // was rejected before it could be applied.  Preserve the structured
    // diagnostic without adding the generic ambiguity marker so the caller
    // can rotate the conversation and replay complete history.  If a batch
    // already carried an explicit partial-acceptance marker, keep the normal
    // fail-closed wrapper below.
    if cursor_error_is_kv_blob_overflow(&error)
        && live_error_is_kv_blob_overflow_replayable(&error.client_message())
    {
        return error;
    }
    let CursorError {
        status,
        message,
        detail,
        retry_after,
    } = error;
    CursorError::new(
        status,
        format!(
            "Cursor BidiAppend {operation} failed; acceptance is ambiguous: {}",
            message
        ),
        detail,
    )
    .with_retry_after(retry_after)
}

impl ClientOutbound {
    async fn send_connect_frame(&self, frame: Bytes) -> Result<(), CursorError> {
        let timeout = Duration::from_secs(env_u64("CCP_CURSOR_SEND_TIMEOUT_SECS", 5));
        self.send_connect_frame_with_options(frame, timeout, 0, Duration::ZERO)
            .await
    }

    /// Retry a response/control frame when a bounded BiDi body channel is
    /// briefly full. Tool-result ResumeBatch sends intentionally use
    /// [`send_connect_frame`] directly so cancellation can preempt the single
    /// bounded wait; those frames have a separate acceptance/reconnect policy.
    async fn send_connect_frame_with_retry(&self, frame: Bytes) -> Result<(), CursorError> {
        let timeout = Duration::from_secs(env_u64("CCP_CURSOR_SEND_TIMEOUT_SECS", 5));
        let retries = env_u64_allow_zero("CCP_CURSOR_SEND_RETRIES", DEFAULT_BIDI_SEND_RETRIES)
            .min(MAX_BIDI_SEND_RETRIES) as u32;
        let backoff = Duration::from_millis(
            env_u64_allow_zero(
                "CCP_CURSOR_SEND_RETRY_BACKOFF_MS",
                DEFAULT_BIDI_SEND_RETRY_BACKOFF_MS,
            )
            .min(MAX_BIDI_SEND_RETRY_BACKOFF_MS),
        );
        self.send_connect_frame_with_options(frame, timeout, retries, backoff)
            .await
    }

    async fn send_connect_frame_with_options(
        &self,
        frame: Bytes,
        attempt_timeout: Duration,
        max_retries: u32,
        retry_backoff: Duration,
    ) -> Result<(), CursorError> {
        match self {
            Self::Bidi(tx) => {
                let mut attempt = 0u32;
                loop {
                    match tokio::time::timeout(attempt_timeout, tx.send(Ok(frame.clone()))).await {
                        Ok(Ok(())) => return Ok(()),
                        Ok(Err(_)) => {
                            return Err(CursorError::internal("Cursor BiDi request stream closed"));
                        }
                        // Tokio's bounded-channel send is cancellation-safe:
                        // if this times out, the frame was not queued and may
                        // be retried without duplicating an upstream message.
                        Err(_) if attempt < max_retries => {
                            attempt += 1;
                            let delay = retry_backoff.checked_mul(attempt).unwrap_or(retry_backoff);
                            if !delay.is_zero() {
                                tokio::time::sleep(delay).await;
                            }
                        }
                        Err(_) => {
                            return Err(CursorError::new(
                                504,
                                "Cursor BiDi request stream send timed out",
                                None,
                            ));
                        }
                    }
                }
            }
            Self::Http1(session) => {
                match tokio::time::timeout(attempt_timeout, session.append_connect_or_raw(&frame))
                    .await
                {
                    Ok(Ok(())) => Ok(()),
                    Ok(Err(error)) => Err(ambiguous_http1_append_error(error, "send")),
                    // Dropping a unary HTTP request future cannot prove that
                    // Cursor did not accept it. Never reconnect and replay it.
                    Err(_) => Err(CursorError::new(
                        504,
                        "Cursor BidiAppend timed out; acceptance is ambiguous",
                        None,
                    )),
                }
            }
        }
    }

    /// Best-effort send for keepalives — never block the BiDi read loop.
    /// Full queues drop this heartbeat tick; the next interval still fires.
    /// HTTP/1 BidiAppend is spawned so a slow append cannot stall upstream reads
    /// (CLI's duplex heartbeats never serialize behind unary append RTTs).
    fn try_send_heartbeat_frame(&self, frame: Bytes) -> bool {
        match self {
            Self::Bidi(tx) => matches!(tx.try_send(Ok(frame)), Ok(())),
            Self::Http1(session) => {
                let session = session.clone();
                tokio::spawn(async move {
                    let _ = session.append_connect_or_raw(&frame).await;
                });
                true
            }
        }
    }
}

/// Fan-out from the BiDi driver to Anthropic SSE. Sized for Fable max-effort
/// thinking bursts so we rarely block the upstream read loop.
const LIVE_EVENT_CHANNEL_CAP: usize = 512;

/// Merge consecutive thinking/text deltas only when the fan-out is at least
/// half full. Healthy queues stay 1:1 so Claude Code paints at Cursor cadence.
const COALESCE_WINDOW: Duration = Duration::from_millis(8);
const COALESCE_MAX_CHARS: usize = 4096;
const MAX_CONSECUTIVE_DECODE_FAILURES: u32 = 8;

/// Claude Code 2.1.193 `AskUserQuestion` chip/tag max (`Qzi = 12`).
const ASK_USER_QUESTION_HEADER_MAX: usize = 12;

/// Nested Workflow POSTs share `X-Claude-Code-Session-Id` (`kt()` is not
/// rotated). The nested difference is additive headers
/// `x-claude-code-agent-id` + `x-claude-code-parent-agent-id`. Concurrent live
/// runs are keyed by `(session_id, agent_id)` — never a new session UUID.
const PARENT_RUN_PREFIX: &str = "p:";
const AGENT_RUN_PREFIX: &str = "a:";
/// Prefix used when an account-scoped identity is folded into the registry
/// agent component.  Keeping this as a length-prefixed opaque component means
/// account digests and Claude agent ids can contain arbitrary punctuation
/// without colliding with the legacy `(session, agent)` key format.
const ACCOUNT_SCOPED_AGENT_PREFIX: &str = "acctv1:";

/// Identity for a Claude Code Messages POST that may be a nested agent.
///
/// `mod.rs` / `server.rs` should pass `x-claude-code-agent-id` and
/// `x-claude-code-parent-agent-id` here. Absent `agent_id` keeps one run per
/// session (legacy behavior).
#[derive(Debug, Clone, Copy, Default)]
pub struct LiveRunIdentity<'a> {
    pub session_id: &'a str,
    pub agent_id: Option<&'a str>,
    pub parent_agent_id: Option<&'a str>,
    /// Stable account identity (normally a one-way digest of the bearer).
    /// `None` preserves the pre-account-routing key format for compatibility
    /// callers and older tests.
    pub account_key: Option<&'a str>,
}

/// Prompt/image recovery hints captured by the request handler before it
/// renders a checkpoint delta.  KV-store normalization can rotate the
/// conversation between that snapshot and the actual BiDi open; in that case
/// the delta belongs to the old binding and the complete Anthropic history
/// must be sent to the fresh conversation.
#[derive(Debug, Clone, Copy, Default)]
pub(crate) struct LiveStartRecovery<'a> {
    pub expected_conversation_id: Option<&'a str>,
    pub reset_user_text: Option<&'a str>,
    pub reset_images: Option<&'a [CursorSelectedImage]>,
}

impl<'a> LiveRunIdentity<'a> {
    pub fn parent(session_id: &'a str) -> Self {
        Self {
            session_id,
            agent_id: None,
            parent_agent_id: None,
            account_key: None,
        }
    }

    pub fn is_nested(&self) -> bool {
        self.agent_id
            .map(str::trim)
            .is_some_and(|id| !id.is_empty())
            && self
                .parent_agent_id
                .map(str::trim)
                .is_some_and(|id| !id.is_empty())
    }
}

/// Registry / Cursor-conversation key for a live run.
///
/// Components are length-prefixed so arbitrary session/agent strings cannot
/// collide with a parent key or with each other.
pub fn live_run_key(session_id: &str, agent_id: Option<&str>) -> String {
    match agent_id.map(str::trim).filter(|id| !id.is_empty()) {
        Some(agent) => format!(
            "{AGENT_RUN_PREFIX}{}:{session_id}{}:{agent}",
            session_id.len(),
            agent.len()
        ),
        None => format!("{PARENT_RUN_PREFIX}{}:{session_id}", session_id.len()),
    }
}

/// Fold a stable account identity into the optional agent component used by
/// the existing registry API.  The registry deliberately keeps its public
/// `(session_id, agent_id)` methods unchanged so legacy callers continue to
/// work; account-aware request paths pass the returned component instead.
pub(crate) fn account_scoped_agent_id(
    account_key: Option<&str>,
    agent_id: Option<&str>,
) -> Option<String> {
    let account = account_key.map(str::trim).filter(|value| !value.is_empty());
    let agent = agent_id.map(str::trim).filter(|value| !value.is_empty());
    let Some(account) = account else {
        return agent.map(str::to_string);
    };
    let agent = agent.unwrap_or("");
    Some(format!(
        "{ACCOUNT_SCOPED_AGENT_PREFIX}{}:{}:{}:{}",
        account.len(),
        account,
        agent.len(),
        agent
    ))
}

pub fn live_run_key_for(identity: LiveRunIdentity<'_>) -> String {
    let agent = account_scoped_agent_id(identity.account_key, identity.agent_id);
    live_run_key(identity.session_id, agent.as_deref())
}

fn claude_session_of(run_key: &str) -> &str {
    let encoded = run_key
        .strip_prefix(PARENT_RUN_PREFIX)
        .or_else(|| run_key.strip_prefix(AGENT_RUN_PREFIX));
    let Some(encoded) = encoded else {
        return run_key;
    };
    let Some((length, remainder)) = encoded.split_once(':') else {
        return run_key;
    };
    let Ok(length) = length.parse::<usize>() else {
        return run_key;
    };
    remainder.get(..length).unwrap_or(run_key)
}

fn channel_backpressured(remaining: usize, cap: usize) -> bool {
    cap > 0 && remaining.saturating_mul(2) <= cap
}

