    fn test_generation_permit() -> LiveGenerationPermit {
        LiveGenerationPermit::default()
    }

    #[tokio::test]
    async fn pre_cancelled_initial_open_never_crosses_the_acceptance_boundary() {
        let (_cancel_tx, mut cancel_rx) = watch::channel(true);
        let open_guard = Arc::new(LiveUpstreamOpenGuard {
            dispatched: Arc::new(AtomicBool::new(false)),
            operation_key: "pre-cancelled-test".into(),
            fingerprint: 1,
            owner_token: "owner".into(),
        });
        let operation_polled = Arc::new(AtomicBool::new(false));
        let polled = Arc::clone(&operation_polled);
        let operation = std::future::poll_fn(move |_| {
            polled.store(true, Ordering::Release);
            std::task::Poll::Ready(Ok::<_, CursorError>(()))
        });

        let error = race_initial_live_operation(Some(&mut cancel_rx), Some(&open_guard), operation)
            .await
            .expect_err("ready cancellation must win");

        assert_eq!(error.status, 409);
        assert!(!open_guard.dispatched.load(Ordering::Acquire));
        assert!(
            !operation_polled.load(Ordering::Acquire),
            "a cancelled half-open owner must not poll or send the user Run"
        );
    }

    #[test]
    fn generation_permit_releases_between_segments_before_native_batch_exposure() {
        let mut generation_permit = Some(LiveGenerationPermit::default());
        let mut pending = PendingExecState::for_run("between-segments-run");
        assert!(pending.queue(pending_exec(1, "read-call"), Duration::from_secs(30)));
        assert!(
            pending.awaiting().is_empty() && pending.has_outstanding_native(),
            "the native tool is still collecting, not exposed"
        );
        let sink = None;

        release_generation_permit_between_segments(&sink, &mut generation_permit);

        assert!(
            generation_permit.as_ref().is_some_and(|permit| {
                permit._total_permit.is_none() && permit._start_permit.is_none()
            }),
            "a driver without a downstream segment must drop its unused start token"
        );
    }

    #[tokio::test]
    async fn generation_permit_releases_after_native_tool_handoff() {
        let generation_permit = LiveGenerationPermit::default();
        let (upstream_tx, upstream_rx) = mpsc::channel(4);
        let (request_tx, _request_rx) = mpsc::channel(8);
        let (command_tx, command_rx) = mpsc::channel(4);
        let (event_tx, mut event_rx) = mpsc::channel(8);
        let pending_shared = Arc::new(Mutex::new(Vec::new()));
        let completed = Arc::new(AtomicBool::new(false));
        let cancel_requested = Arc::new(AtomicBool::new(false));

        let driver = tokio::spawn(drive_live_run(
            upstream_rx,
            upstream_tx.clone(),
            tokio::spawn(std::future::pending::<()>()),
            ClientOutbound::Bidi(request_tx),
            command_rx,
            event_tx,
            Arc::clone(&pending_shared),
            Arc::new(Mutex::new(None)),
            Arc::clone(&completed),
            Arc::clone(&cancel_requested),
            Some(BTreeSet::from(["Read".into()])),
            "generation-lease-handoff".into(),
            "generation-lease-run".into(),
            HashMap::new(),
            "read the file".into(),
            RequestContext::default(),
            test_reconnect_context(),
            generation_permit,
        ));

        let mut payload = Vec::new();
        proto::AgentServerMessage {
            exec_server_message: Some(ExecServerMessage {
                id: 1,
                exec_id: Some("read-exec".into()),
                read_args: Some(ExecReadArgs {
                    path: "/tmp/input.txt".into(),
                    tool_call_id: "read-call".into(),
                    offset: None,
                    limit: None,
                }),
                ..Default::default()
            }),
            ..Default::default()
        }
        .encode(&mut payload)
        .expect("encode read tool");
        upstream_tx
            .send(Ok(Some(encode_connect_frame(payload, 0))))
            .await
            .expect("send read tool");

        let event = tokio::time::timeout(Duration::from_secs(2), event_rx.recv())
            .await
            .expect("native tool was not exposed")
            .expect("native tool event");
        let tool_use_id = match event {
            Ok(LiveRunEvent::NativeToolBatch(tools)) => tools[0].tool_use_id.clone(),
            other => panic!("expected native tool batch, got {other:?}"),
        };
        assert!(
            !completed.load(Ordering::Acquire),
            "the live driver must remain resumable after exposing native tools"
        );
        assert_eq!(
            pending_shared
                .lock()
                .unwrap_or_else(|error| error.into_inner())
                .len(),
            1
        );

        let resume_generation_permit = LiveGenerationPermit::default();
        let (resume_sink, _resume_events) = mpsc::channel(8);
        let (ack_tx, ack_rx) = oneshot::channel();
        command_tx
            .send(RunCommand::ResumeBatch {
                tool_results: vec![(
                    tool_use_id,
                    serde_json::json!({"type":"tool_result","content":"done"}),
                )],
                sink: resume_sink,
                ack: ack_tx,
                permit: LiveResumePermit {
                    in_flight: Arc::new(ResumeAdmission::with_state(RESUME_ADMISSION_IN_FLIGHT)),
                },
                generation_permit: resume_generation_permit,
                dispatch_state: Arc::new(AtomicU8::new(RESUME_DISPATCH_WAITING)),
                accepted_fingerprint: None,
            })
            .await
            .expect("dispatch resume");
        ack_rx
            .await
            .expect("resume acknowledgement")
            .expect("resume accepted");

        cancel_requested.store(true, Ordering::Release);
        command_tx
            .send(RunCommand::Cancel { ack: None })
            .await
            .expect("cancel driver");
        tokio::time::timeout(Duration::from_secs(2), driver)
            .await
            .expect("driver did not stop")
            .expect("driver join");
    }

    #[tokio::test(flavor = "current_thread")]
    async fn resume_generation_admission_does_not_spend_driver_dispatch_timeout() {
        let (command_tx, mut command_rx) = mpsc::channel(1);
        let handle = Arc::new(CursorLiveRunHandle {
            run_id: "resume-admission-budget".into(),
            command_tx,
            pending: Arc::new(Mutex::new(vec![pending_exec(1, "tool-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(0)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let driver = tokio::spawn(async move {
            let RunCommand::ResumeBatch {
                ack,
                dispatch_state,
                ..
            } = command_rx.recv().await.expect("resume command")
            else {
                panic!("expected resume command");
            };
            dispatch_state
                .compare_exchange(
                    RESUME_DISPATCH_WAITING,
                    RESUME_DISPATCH_STARTED,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .expect("accept resume command");
            ack.send(Ok(())).expect("acknowledge resume");
        });

        let resume_handle = Arc::clone(&handle);
        let resume = tokio::spawn(async move {
            resume_handle
                .resume_batch_within(
                    vec![(
                        "tool-1".into(),
                        serde_json::json!({"type":"tool_result","content":"done"}),
                    )],
                    Duration::from_millis(50),
                )
                .await
        });
        let events = tokio::time::timeout(Duration::from_secs(1), resume)
            .await
            .expect("resume did not finish after generation admission")
            .expect("resume task")
            .expect("resume dispatch must not wait on a local generation gate");
        drop(events);
        driver.await.expect("mock driver");
    }

    #[tokio::test]
    async fn concurrent_resume_is_retryable_capacity_error() {
        let (command_tx, _command_rx) = mpsc::channel(1);
        let handle = CursorLiveRunHandle {
            run_id: "concurrent-resume".into(),
            command_tx,
            pending: Arc::new(Mutex::new(vec![pending_exec(1, "tool-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::with_state(RESUME_ADMISSION_IN_FLIGHT)),
            request_fingerprint: Arc::new(AtomicU64::new(0)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        };

        let error = handle
            .resume_batch_within(
                vec![(
                    "tool-1".into(),
                    serde_json::json!({"type":"tool_result","content":"done"}),
                )],
                Duration::from_millis(50),
            )
            .await
            .expect_err("a concurrent resume must be rejected");
        assert_eq!(
            error.status, 503,
            "an alive resume is local capacity contention, not an invalid request"
        );
    }

    #[tokio::test]
    async fn accepted_resume_commits_its_sampling_stage_fingerprint() {
        let (command_tx, mut command_rx) = mpsc::channel(1);
        let handle = Arc::new(CursorLiveRunHandle {
            run_id: "resume-stage-fingerprint".into(),
            command_tx,
            pending: Arc::new(Mutex::new(vec![pending_exec(1, "tool-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(11)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let driver = tokio::spawn(async move {
            let Some(RunCommand::ResumeBatch {
                ack,
                dispatch_state,
                accepted_fingerprint,
                ..
            }) = command_rx.recv().await
            else {
                panic!("expected resume command");
            };
            dispatch_state
                .compare_exchange(
                    RESUME_DISPATCH_WAITING,
                    RESUME_DISPATCH_STARTED,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .expect("accept resume");
            if let Some((target, fingerprint)) = accepted_fingerprint {
                target.store(fingerprint, Ordering::Release);
            }
            ack.send(Ok(())).expect("ack resume");
        });

        let events = handle
            .resume_batch_for_operation(
                vec![(
                    "tool-1".into(),
                    serde_json::json!({"type":"tool_result","content":"done"}),
                )],
                22,
            )
            .await
            .expect("accepted resume");
        drop(events);
        driver.await.expect("driver");
        assert_eq!(
            handle.request_fingerprint(),
            22,
            "an exact retry of the tool-result sampling stage must not execute twice"
        );
    }

    #[tokio::test(flavor = "current_thread")]
    async fn resume_generation_admission_stops_when_driver_is_cancelled() {
        let (command_tx, command_rx) = mpsc::channel(1);
        drop(command_rx);
        let handle = Arc::new(CursorLiveRunHandle {
            run_id: "cancelled-resume-admission".into(),
            command_tx,
            pending: Arc::new(Mutex::new(vec![pending_exec(1, "tool-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(0)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let error = handle
            .resume_batch_within(
                vec![(
                    "tool-1".into(),
                    serde_json::json!({"type":"tool_result","content":"done"}),
                )],
                Duration::from_millis(50),
            )
            .await
            .expect_err("cancelled admission must not dispatch");
        assert_eq!(error.status, 502);
        assert!(
            live_resume_error_is_dead_driver(&error),
            "a closed driver must transition the caller to replacement handling"
        );
        assert!(
            handle.resume_in_flight.state() == RESUME_ADMISSION_IDLE,
            "cancellation must release the exact-once resume guard"
        );
    }

