    #[tokio::test]
    async fn http1_append_timeout_does_not_replay() {
        use std::sync::atomic::AtomicUsize;
        use tokio::io::AsyncReadExt;

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind stalled BidiAppend server");
        let address = listener.local_addr().expect("server address");
        let attempts = Arc::new(AtomicUsize::new(0));
        let server_attempts = Arc::clone(&attempts);
        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.expect("accept BidiAppend");
            server_attempts.fetch_add(1, Ordering::SeqCst);
            let mut request = [0u8; 4096];
            let _ = socket.read(&mut request).await;
            std::future::pending::<()>().await;
        });

        let outbound = ClientOutbound::Http1(BidiAppendSession::new(
            reqwest::Client::new(),
            format!("http://{address}"),
            "token".into(),
            "request-id".into(),
            vec![],
        ));
        let error = outbound
            .send_connect_frame_with_options(
                Bytes::from_static(b"frame"),
                Duration::from_millis(25),
                4,
                Duration::from_millis(1),
            )
            .await
            .expect_err("a stalled HTTP/1 append must time out");
        assert_eq!(error.status, 504);
        assert!(error.message.contains("acceptance is ambiguous"), "{error}");

        tokio::time::sleep(Duration::from_millis(50)).await;
        assert_eq!(attempts.load(Ordering::SeqCst), 1);
        server.abort();
        let _ = server.await;
    }

    #[tokio::test]
    async fn cancelling_in_flight_http1_control_close_preserves_ambiguity() {
        use tokio::io::AsyncReadExt;

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind stalled BidiAppend server");
        let address = listener.local_addr().expect("server address");
        let (accepted_tx, accepted_rx) = oneshot::channel();
        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.expect("accept BidiAppend");
            let mut request = [0u8; 4096];
            let bytes_read = socket.read(&mut request).await.expect("read BidiAppend");
            assert!(bytes_read > 0, "empty BidiAppend request");
            let _ = accepted_tx.send(());
            std::future::pending::<()>().await;
        });
        let mut outbound = ClientOutbound::Http1(BidiAppendSession::new(
            reqwest::Client::new(),
            format!("http://{address}"),
            "token".into(),
            "request-id".into(),
            vec![],
        ));
        let (upstream_tx, mut upstream) = mpsc::channel(1);
        let mut driver_upstream_tx = upstream_tx;
        let mut upstream_pump = tokio::spawn(std::future::pending::<()>());
        let cancel_requested = Arc::new(AtomicBool::new(false));
        let cancel_signal = Arc::clone(&cancel_requested);
        let terminal_error = Arc::new(Mutex::new(None));
        let mut reconnect = test_reconnect_context();
        let mut decoder = ConnectFrameDecoder::new();
        let latest_checkpoint = Some(vec![0x08, 0x01]);
        let kv_blobs = HashMap::new();
        let mut pending = PendingExecState::default();
        assert!(pending.queue(
            pending_exec(1, "control-close-tool"),
            Duration::from_secs(1)
        ));
        let mut reconnect_attempts = 0;
        let mut last_progress = Instant::now();
        let mut resume_grace_until = None;

        let cancel = async move {
            accepted_rx.await.expect("BidiAppend accepted by mock");
            cancel_signal.store(true, Ordering::Release);
        };
        let reconnecting = try_live_reconnect(
            &mut reconnect,
            &mut outbound,
            &mut upstream,
            &mut driver_upstream_tx,
            &mut upstream_pump,
            cancel_requested.as_ref(),
            &terminal_error,
            &mut decoder,
            &latest_checkpoint,
            &kv_blobs,
            &mut pending,
            &mut reconnect_attempts,
            10,
            &mut last_progress,
            &mut resume_grace_until,
            Duration::from_secs(1),
            Instant::now() + Duration::from_secs(10),
        );
        let (outcome, ()) = tokio::join!(reconnecting, cancel);
        server.abort();
        let _ = server.await;

        let LiveReconnectOutcome::Failed(detail) = outcome else {
            panic!("expected failed reconnect");
        };
        assert!(detail.contains("ambiguous"), "{detail}");
        let stored = terminal_error
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .as_ref()
            .map(|outcome| outcome.message.clone())
            .expect("ambiguous terminal outcome");
        assert!(stored.contains("ambiguous"), "{stored}");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn reconnect_open_wave_is_bounded_process_wide() {
        use std::sync::atomic::AtomicUsize;

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind stalled H2 server");
        let address = listener.local_addr().expect("server address");
        let accepted = Arc::new(AtomicUsize::new(0));
        let server_accepted = Arc::clone(&accepted);
        let server = tokio::spawn(async move {
            let mut held = Vec::new();
            loop {
                let (socket, _) = listener.accept().await.expect("accept H2 reconnect");
                server_accepted.fetch_add(1, Ordering::SeqCst);
                held.push(socket);
            }
        });

        let recovery_open_gate = Arc::new(Semaphore::new(4));
        let cancel_requested = Arc::new(AtomicBool::new(false));
        let mut reconnects = Vec::new();
        for index in 0..8u8 {
            let cancel_requested = Arc::clone(&cancel_requested);
            let recovery_open_gate = Arc::clone(&recovery_open_gate);
            reconnects.push(tokio::spawn(async move {
                let mut reconnect = test_reconnect_context();
                reconnect.http.base_url = format!("http://{address}");
                reconnect.recovery_open_gate = recovery_open_gate;
                reconnect.session_id = format!("reconnect-wave-{index}");
                reconnect.conversation_id = Some(format!("conversation-{index}"));
                reconnect.opening_checkpoint = Some(vec![0x08, index]);
                let (request_tx, _request_rx) = mpsc::channel(1);
                let mut outbound = ClientOutbound::Bidi(request_tx);
                let (upstream_tx, mut upstream) = mpsc::channel(1);
                let mut driver_upstream_tx = upstream_tx;
                let mut upstream_pump = tokio::spawn(std::future::pending::<()>());
                let terminal_error = Arc::new(Mutex::new(None));
                let mut decoder = ConnectFrameDecoder::new();
                let latest_checkpoint = Some(vec![0x08, index]);
                let mut pending = PendingExecState::default();
                let mut reconnect_attempts = 0;
                let mut last_progress = Instant::now();
                let mut resume_grace_until = None;
                try_live_reconnect(
                    &mut reconnect,
                    &mut outbound,
                    &mut upstream,
                    &mut driver_upstream_tx,
                    &mut upstream_pump,
                    cancel_requested.as_ref(),
                    &terminal_error,
                    &mut decoder,
                    &latest_checkpoint,
                    &HashMap::new(),
                    &mut pending,
                    &mut reconnect_attempts,
                    10,
                    &mut last_progress,
                    &mut resume_grace_until,
                    Duration::from_secs(1),
                    Instant::now() + Duration::from_secs(10),
                )
                .await
            }));
        }

        tokio::time::timeout(Duration::from_secs(5), async {
            while accepted.load(Ordering::SeqCst) < 4 {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("four reconnect opens must reach the local gate");
        tokio::time::sleep(Duration::from_millis(100)).await;
        let opened = accepted.load(Ordering::SeqCst);
        assert_eq!(
            opened, 4,
            "a shared H2 failure must hold later opens behind the process gate"
        );

        cancel_requested.store(true, Ordering::Release);
        for reconnect in reconnects {
            let _ = tokio::time::timeout(Duration::from_secs(1), reconnect).await;
        }
        server.abort();
        let _ = server.await;
    }

