        assert!(live_reconnect_allow_h1_fallback(false, false));
        assert!(
            !live_reconnect_allow_h1_fallback(false, true),
            "464/421 must not retry HTTP/1 on the same incident"
        );
        assert!(!live_reconnect_allow_h1_fallback(true, false));
