    #[test]
    fn retryable_terminal_error_clears_durable_marker_before_same_operation_retry() {
        let _ledger = super::super::operation_ledger::OPERATION_LEDGER_TEST_LOCK
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let _registry = lock_live_registry_for_test();
        let dir = tempfile::tempdir().unwrap();
        let _restore = super::super::operation_ledger::test_operation_dir_guard(dir.path());
        let session = format!("empty-turn-ledger-release-{}", uuid::Uuid::new_v4());
        let key = live_run_key(&session, None);
        let fingerprint = 0x7a11;
        LiveRunRegistry::clear();
        let handle = durable_running_handle(&session, "empty-turn-ledger-run", fingerprint);
        store_terminal_error(
            &handle.terminal_error,
            "Cursor upstream finished this turn without text or tool calls; retry this turn (stale Cursor conversation reset; retry this message to continue)",
        );
        handle.completed.store(true, Ordering::Release);

        assert!(matches!(
            LiveRunRegistry::probe_run(&session, None),
            LiveRunProbe::Free
        ));
        // The in-memory slot and durable operation marker must transition
        // together.  A same-fingerprint fresh-history retry should be able to
        // claim immediately rather than seeing the old Dispatched marker as
        // an ambiguous 409/503 tombstone.
        assert_eq!(
            super::super::operation_ledger::admit(&key, fingerprint),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        assert_eq!(
            super::super::operation_ledger::claim(&key, fingerprint, "retry-owner"),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        assert!(
            super::super::operation_ledger::clear_if_owner(&key, fingerprint, "retry-owner")
                .unwrap()
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn policy_rate_limit_429_is_terminal_never_seals_and_frees_the_slot() {
        let free_plan = "Connect error 429: ERROR_RATE_LIMITED_CHANGEABLE: Named models unavailable — Free plans can only use Auto. [resource_exhausted]";
        assert!(
            !live_error_is_same_request_retryable(free_plan),
            "policy 429s must surface verbatim on the first upstream response"
        );
        let err = CursorError::new(429, free_plan, None);
        assert!(!cursor_start_error_is_same_request_retryable(&err));
        assert!(!live_start_error_seals_tombstone(&err));
        assert!(!terminal_error_is_ambiguous_accept(free_plan));

        let quota = "Connect error 429: ERROR_PRO_USER_RATE_LIMIT_EXCEEDED: Rate limit exceeded. [resource_exhausted]";
        assert!(!live_error_is_same_request_retryable(quota));
        assert!(!terminal_error_is_ambiguous_accept(quota));

        // A policy 429 folded into stall/reconnect wrapper text means an
        // ACCEPTED Run stalled and only the reconnect was rejected — the
        // original Run's state is unknown, so it must stay ambiguous
        // (fail-closed) to prevent duplicate execution.
        let wrapped = format!(
            "Cursor resume produced no progress before the stream stalled (reconnect failed: {free_plan})"
        );
        assert!(terminal_error_is_ambiguous_accept(&wrapped));
    }

    #[test]
    fn policy_rate_limit_terminal_error_frees_slot_and_keeps_message() {
        let _registry = lock_live_registry_for_test();
        let session = format!("policy-429-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let text = "Connect error 429: ERROR_RATE_LIMITED_CHANGEABLE: Named models unavailable — Free plans can only use Auto. [resource_exhausted]";
        let (command_tx, _command_rx) = mpsc::channel(1);
        let handle = Arc::new(CursorLiveRunHandle {
            run_id: "policy-429-run".into(),
            command_tx,
            pending: Arc::new(Mutex::new(Vec::new())),
            terminal_error: Arc::new(Mutex::new(Some(TerminalOutcome {
                message: text.into(),
                created_at: Instant::now(),
            }))),
            completed: Arc::new(AtomicBool::new(true)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(0)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(handle)
            .expect("insert policy 429 failure");
        match LiveRunRegistry::probe_run(&session, None) {
            LiveRunProbe::TerminalError(delivered) => assert_eq!(
                delivered, text,
                "the verbatim policy 429 must be delivered once"
            ),
            LiveRunProbe::Free => panic!("expected TerminalError, got Free"),
            LiveRunProbe::Occupied => panic!("expected TerminalError, got Occupied"),
        }
        assert!(
            matches!(
                LiveRunRegistry::probe_run(&session, None),
                LiveRunProbe::Free
            ),
            "the slot must already be free for the next POST"
        );
        LiveRunRegistry::clear();
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)]
    async fn trailing_missing_conversation_end_overrides_prior_chunk_turn_ended() {
        let _guard = super::super::conversation::STORE_TEST_LOCK.lock().unwrap();
        super::super::conversation::reset_for_test();
        let session_id = "sess-trailing-conversation-missing";
        let original =
            super::super::conversation::continuation_for(Some(session_id)).conversation_id;
        let checkpoint = vec![0x08, 0x01];
        let stale_blobs = HashMap::from([(vec![0xaa], vec![0xbb])]);
        super::super::conversation::save_checkpoint(session_id, checkpoint.clone());
        super::super::conversation::merge_blobs(session_id, &stale_blobs);

        let (upstream_tx, upstream_rx) = mpsc::channel(2);
        let (request_tx, _request_rx) = mpsc::channel(1);
        let (_command_tx, command_rx) = mpsc::channel(1);
        let (event_tx, _events) = mpsc::channel(8);
        let terminal_error = Arc::new(Mutex::new(None));
        let completed = Arc::new(AtomicBool::new(false));
        let mut reconnect = test_reconnect_context();
        reconnect.conversation_id = original.clone();
        reconnect.opening_checkpoint = Some(checkpoint);
        let driver = tokio::spawn(drive_live_run(
            upstream_rx,
            upstream_tx.clone(),
            tokio::spawn(std::future::pending::<()>()),
            ClientOutbound::Bidi(request_tx),
            command_rx,
            event_tx,
            Arc::new(Mutex::new(Vec::new())),
            Arc::clone(&terminal_error),
            Arc::clone(&completed),
            Arc::new(AtomicBool::new(false)),
            None,
            session_id.into(),
            "trailing-end-run".into(),
            stale_blobs,
            "continue".into(),
            RequestContext::default(),
            reconnect,
            test_generation_permit(),
        ));

        let mut turn_payload = Vec::new();
        proto::AgentServerMessage {
            interaction_update: Some(InteractionUpdate {
                turn_ended: Some(TurnEnded {
                    output_tokens: Some(1),
                    ..Default::default()
                }),
                ..Default::default()
            }),
            ..Default::default()
        }
        .encode(&mut turn_payload)
        .expect("encode turn_ended");
        let turn_ended = encode_connect_frame(turn_payload, 0);
        let missing_end = encode_connect_frame(
            serde_json::to_vec(&serde_json::json!({
                "error": {
                    "code": "internal",
                    "message": "ERROR_CUSTOM_MESSAGE: Internal error",
                    "details": [{
                        "debug": {
                            "error": "ERROR_CUSTOM_MESSAGE",
                            "details": {
                                "title": "Internal error",
                                "detail": "Conversation data missing (14 missing blobs: abc)"
                            }
                        }
                    }]
                }
            }))
            .unwrap(),
            FLAG_END,
        );
        upstream_tx
            .send(Ok(Some(turn_ended)))
            .await
            .expect("send turn_ended chunk");
        tokio::time::sleep(Duration::from_millis(10)).await;
        upstream_tx
            .send(Ok(Some(missing_end)))
            .await
            .expect("send trailing END chunk");
        tokio::time::timeout(Duration::from_secs(2), driver)
            .await
            .expect("driver timeout")
            .expect("driver");

        let error = terminal_error
            .lock()
            .unwrap_or_else(|poison| poison.into_inner())
            .as_ref()
            .map(|outcome| outcome.message.clone())
            .expect("trailing END must be terminal");
        assert!(error.contains("conversation reset"), "{error}");
        let recovered = super::super::conversation::continuation_for(Some(session_id));
        assert_ne!(recovered.conversation_id, original);
        assert!(!recovered.has_checkpoint);
        assert!(recovered.pre_fetched_blobs.is_empty());
    }

