    #[test]
    fn start_error_classifies_http_body_detail_not_just_message() {
        let invoice = CursorError::new(
            502,
            "Cursor upstream HTTP 502",
            Some(
                "You have an unpaid invoice — Visit cursor.com/dashboard and pay your invoice"
                    .into(),
            ),
        );
        assert!(
            !cursor_start_error_is_same_request_retryable(&invoice),
            "billing text in the HTTP body must fail closed"
        );

        let geo = CursorError::new(
            403,
            "Cursor upstream HTTP 403",
            Some("This model is not available in your country or region".into()),
        );
        assert!(!cursor_start_error_is_same_request_retryable(&geo));

        let missing = CursorError::new(
            400,
            "Cursor upstream HTTP 400",
            Some("Conversation data missing [failed_precondition]".into()),
        );
        assert!(
            cursor_start_error_is_same_request_retryable(&missing),
            "missing conversation in a 4xx body must still same-request retry"
        );

        let open_timeout = CursorError::new(504, "Cursor live open timed out after 20s", None);
        assert!(
            !cursor_start_error_is_same_request_retryable(&open_timeout),
            "response-less live open must seal, not replay Run with a new request id"
        );
        assert!(live_start_error_seals_tombstone(&open_timeout));

        let connect = CursorError::new(502, "Cursor upstream connect failed", None);
        assert!(
            cursor_start_error_is_same_request_retryable(&connect),
            "a refused connect must retry inside this POST"
        );
        assert!(
            !live_start_error_seals_tombstone(&connect),
            "a request that never connected cannot leave an accepted Run"
        );

        let rejected = CursorError::new(503, "Cursor upstream HTTP 503", None);
        assert!(
            !live_start_error_seals_tombstone(&rejected),
            "an explicit upstream rejection must not poison the next grok retry"
        );
    }

    #[test]
    fn initial_bidiappend_timeout_fails_closed_without_replay() {
        let initial = ambiguous_http1_append_error(
            CursorError::new(408, "BidiAppend timed out", None),
            "initial Run",
        );
        assert_eq!(
            initial.message,
            "Cursor BidiAppend initial Run failed; acceptance is ambiguous: BidiAppend timed out"
        );
        assert!(
            !cursor_start_error_is_same_request_retryable(&initial),
            "a timed-out BidiAppend may have accepted the Run and must not be replayed"
        );
        assert!(
            live_start_error_seals_tombstone(&initial),
            "exhausted retries still seal Starting so the next POST is not a duplicate"
        );
        let exhausted = exhausted_live_start_error(initial.clone(), 0);
        assert_eq!(
            exhausted.status, 409,
            "the first ambiguous send must immediately fail closed as 409"
        );
        assert_eq!(exhausted.message, initial.message);

        let mid_stream = ambiguous_http1_append_error(
            CursorError::new(408, "BidiAppend timed out", None),
            "send",
        );
        assert!(
            !cursor_start_error_is_same_request_retryable(&mid_stream),
            "mid-stream BidiAppend timeout must not start a second Run"
        );
        assert!(live_send_failure_is_terminal(&mid_stream));

        let send_wrapper = CursorError::new(
            504,
            "Cursor BidiAppend timed out; acceptance is ambiguous",
            None,
        );
        assert!(
            !cursor_start_error_is_same_request_retryable(&send_wrapper),
            "a timed-out in-flight send must not be replayed as a new Run"
        );
    }

    #[test]
    fn kv_set_then_get_round_trips_the_latest_blob() {
        let key = b"conversation-state".to_vec();
        let mut blobs = HashMap::new();
        let set = KvServerMessage {
            id: 70,
            get_blob_args: None,
            set_blob_args: Some(proto::SetBlobArgs {
                blob_id: key.clone(),
                blob_data: b"state-before".to_vec(),
            }),
            span_context: None,
        };
        let set_frame = encode_kv_reply(&set, &mut blobs).unwrap().unwrap();
        let decoded = super::super::client::decode_upstream_frames(&set_frame).unwrap();
        let set_reply = AgentClientMessage::decode(decoded[0].payload.as_ref()).unwrap();
        assert_eq!(set_reply.kv_client_message.as_ref().unwrap().id, 70);
        assert!(
            set_reply
                .kv_client_message
                .unwrap()
                .set_blob_result
                .unwrap()
                .error
                .is_none()
        );

        let overwrite = KvServerMessage {
            id: 71,
            get_blob_args: None,
            set_blob_args: Some(proto::SetBlobArgs {
                blob_id: key.clone(),
                blob_data: b"state-after".to_vec(),
            }),
            span_context: None,
        };
        encode_kv_reply(&overwrite, &mut blobs).unwrap();

        let get = KvServerMessage {
            id: 72,
            get_blob_args: Some(proto::GetBlobArgs { blob_id: key }),
            set_blob_args: None,
            span_context: None,
        };
        let get_frame = encode_kv_reply(&get, &mut blobs).unwrap().unwrap();
        let decoded = super::super::client::decode_upstream_frames(&get_frame).unwrap();
        let get_reply = AgentClientMessage::decode(decoded[0].payload.as_ref()).unwrap();
        assert_eq!(
            get_reply
                .kv_client_message
                .unwrap()
                .get_blob_result
                .unwrap()
                .blob_data
                .as_deref(),
            Some(b"state-after".as_slice())
        );
    }

    #[test]
    fn kv_running_total_tracks_overwrites_without_scanning_the_map() {
        let key = b"running-total".to_vec();
        let mut blobs = HashMap::new();
        let mut total = 0usize;
        let set =
            |id: u32, data: &[u8], blobs: &mut HashMap<Vec<u8>, Vec<u8>>, total: &mut usize| {
                encode_kv_reply_with_total(
                    &KvServerMessage {
                        id,
                        get_blob_args: None,
                        set_blob_args: Some(proto::SetBlobArgs {
                            blob_id: key.clone(),
                            blob_data: data.to_vec(),
                        }),
                        span_context: None,
                    },
                    blobs,
                    total,
                )
                .expect("small SetBlob should encode")
                .expect("SetBlob should produce a reply");
            };

        set(75, b"12345", &mut blobs, &mut total);
        assert_eq!(total, 5);
        set(76, b"xy", &mut blobs, &mut total);
        assert_eq!(total, 2, "an overwrite replaces, rather than adds, bytes");
        assert_eq!(blobs.get(&key).map(Vec::len), Some(2));
    }

    #[test]
    fn kv_running_total_stays_unchanged_when_growth_is_rejected() {
        let mut blobs: HashMap<Vec<u8>, Vec<u8>> = (0..MAX_LIVE_KV_BLOBS)
            .map(|index| (index.to_be_bytes().to_vec(), Vec::new()))
            .collect();
        let mut total = 0usize;
        let message = KvServerMessage {
            id: 77,
            get_blob_args: None,
            set_blob_args: Some(proto::SetBlobArgs {
                blob_id: b"rejected-growth".to_vec(),
                blob_data: b"would-overflow-count".to_vec(),
            }),
            span_context: None,
        };
        let error = encode_kv_reply_with_total(&message, &mut blobs, &mut total)
            .expect_err("the soft blob-count ceiling must reject growth");
        assert_eq!(error.status, 413);
        assert_eq!(total, 0);
        assert_eq!(blobs.len(), MAX_LIVE_KV_BLOBS);
    }

    #[test]
    fn kv_blob_store_rejects_an_oversized_blob() {
        let mut blobs = HashMap::new();
        let set = KvServerMessage {
            id: 73,
            get_blob_args: None,
            set_blob_args: Some(proto::SetBlobArgs {
                blob_id: b"oversized".to_vec(),
                blob_data: vec![0_u8; MAX_LIVE_KV_BLOB_BYTES + 1],
            }),
            span_context: None,
        };

        let error = encode_kv_reply(&set, &mut blobs).expect_err("oversized KV blob must fail");
        assert_eq!(error.status, 413);
        assert!(blobs.is_empty(), "rejected data must not enter live memory");
    }

    #[test]
    fn kv_blob_store_rejects_growth_at_the_soft_conversation_ceiling() {
        // A long tool-heavy Run can append many blobs after its opening
        // continuation snapshot. Enforce the same headroom during the Run,
        // rather than waiting for the server-equivalent hard count of 4096.
        let mut blobs: HashMap<Vec<u8>, Vec<u8>> = (0..MAX_LIVE_KV_BLOBS)
            .map(|index| (index.to_be_bytes().to_vec(), Vec::new()))
            .collect();
        let set = KvServerMessage {
            id: 74,
            get_blob_args: None,
            set_blob_args: Some(proto::SetBlobArgs {
                blob_id: b"soft-ceiling-next".to_vec(),
                blob_data: b"one-more".to_vec(),
            }),
            span_context: None,
        };

        let error = encode_kv_reply(&set, &mut blobs)
            .expect_err("active KV growth must stop before the hard server ceiling");
        assert_eq!(error.status, 413);
        assert!(live_error_is_kv_blob_overflow(&error.client_message()));
        assert_eq!(blobs.len(), MAX_LIVE_KV_BLOBS);
    }

