    #[test]
    fn ambiguous_reservation_is_durable_after_registry_reset() {
        let _ledger = super::super::operation_ledger::OPERATION_LEDGER_TEST_LOCK
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let _registry = lock_live_registry_for_test();
        let dir = tempfile::tempdir().unwrap();
        let _restore = super::super::operation_ledger::test_operation_dir_guard(dir.path());
        let session = format!("durable-ambiguous-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();

        let mut reservation = LiveRunRegistry::reserve(&session).expect("reserve");
        reservation.set_operation_fingerprint(99);
        assert_eq!(
            reservation.begin_durable_operation(),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        reservation.seal_ambiguous(Instant::now() + LIVE_AMBIGUOUS_OPEN_TTL);
        LiveRunRegistry::clear();

        // The durable marker is keyed by the registry run key, not the raw
        // Claude session id.
        assert!(matches!(
            super::super::operation_ledger::admit(&live_run_key(&session, None), 99),
            super::super::operation_ledger::OperationAdmission::Ambiguous(_)
        ));
    }

    #[test]
    fn stale_reservation_release_cannot_clear_new_owner_durable_marker() {
        let _ledger = super::super::operation_ledger::OPERATION_LEDGER_TEST_LOCK
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let _registry = lock_live_registry_for_test();
        let dir = tempfile::tempdir().unwrap();
        let _restore = super::super::operation_ledger::test_operation_dir_guard(dir.path());
        let session = format!("stale-release-{}", uuid::Uuid::new_v4());
        let key = live_run_key(&session, None);
        LiveRunRegistry::clear();

        let mut stale = LiveRunRegistry::reserve(&session).expect("first reserve");
        stale.set_operation_fingerprint(77);
        assert_eq!(
            stale.begin_durable_operation(),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        {
            let mut runs = LIVE_RUNS.lock().unwrap_or_else(|error| error.into_inner());
            runs.remove_key(&key);
        }
        let mut replacement = LiveRunRegistry::reserve(&session).expect("replacement reserve");
        replacement.set_operation_fingerprint(77);
        assert!(
            super::super::operation_ledger::transfer_owner_if(
                &key,
                77,
                &stale.reservation_id,
                &replacement.reservation_id,
            )
            .unwrap()
        );

        stale.release();

        assert!(matches!(
            super::super::operation_ledger::admit(&key, 77),
            super::super::operation_ledger::OperationAdmission::Ambiguous(_)
        ));
        replacement.release();
        LiveRunRegistry::clear();
    }

    #[test]
    fn dropped_replacement_seals_the_superseded_durable_owner() {
        let _ledger = super::super::operation_ledger::OPERATION_LEDGER_TEST_LOCK
            .lock()
            .unwrap_or_else(|error| error.into_inner());
        let _registry = lock_live_registry_for_test();
        let dir = tempfile::tempdir().unwrap();
        let _restore = super::super::operation_ledger::test_operation_dir_guard(dir.path());
        let session = format!("replacement-drop-owner-{}", uuid::Uuid::new_v4());
        let key = live_run_key(&session, None);
        LiveRunRegistry::clear();

        // Establish the same durable state as an accepted live Run: the
        // reservation owner is transferred to the Cursor run id at insert.
        let mut initial = LiveRunRegistry::reserve(&session).expect("initial reserve");
        initial.set_operation_fingerprint(77);
        assert_eq!(
            initial.begin_durable_operation(),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        assert!(
            super::super::operation_ledger::mark_dispatched_if_owner(
                &key,
                77,
                initial.durable_owner_token(),
            )
            .unwrap()
        );
        let old = dummy_handle("superseded-run");
        old.set_request_fingerprint(77);
        initial.insert(Arc::clone(&old)).expect("insert old run");

        let LiveReplacementClaim::Reserved {
            reservation,
            superseded: Some(_superseded),
        } = LiveRunRegistry::claim_replacement_for_run(&session, None, old.run_id())
        else {
            panic!("accepted run must be replaceable");
        };
        assert_eq!(reservation.durable_owner_token(), old.run_id());

        // Simulate cancellation wait being abandoned while the replacement is
        // protected. Drop must update the existing Dispatched record through
        // the superseded run owner; using the fresh reservation UUID would
        // fail the owner check and leave the marker permanently Dispatched.
        reservation.protect_on_drop();
        drop(reservation);
        assert!(matches!(
            super::super::operation_ledger::admit(&key, 77),
            super::super::operation_ledger::OperationAdmission::Ambiguous(_)
        ));

        // A different operation can atomically rotate a known ambiguous
        // marker. This is the distinguishing assertion: an uncleared
        // Dispatched marker would reject this claim as Ambiguous.
        let mut next =
            LiveRunRegistry::claim_ambiguous_release_for_new_operation(&session, None, 88)
                .expect("new operation should replace scoped tombstone");
        next.set_operation_fingerprint(88);
        assert_eq!(
            next.begin_durable_operation(),
            super::super::operation_ledger::OperationAdmission::Allowed
        );
        next.release();
        LiveRunRegistry::clear();
    }

    #[test]
    fn success_tombstone_blocks_identical_retry_but_allows_a_new_prompt() {
        let _registry = lock_live_registry_for_test();
        let session = format!("success-tombstone-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let handle = dummy_handle("ok-run");
        handle.set_request_fingerprint(42);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(handle)
            .expect("insert");
        LiveRunRegistry::seal_success_if(&session, "ok-run", None);
        assert!(LiveRunRegistry::is_occupied(&session));
        LiveRunRegistry::release_success_if_new_request(&session, None, 42);
        assert!(
            LiveRunRegistry::is_occupied(&session),
            "retrying the same request must not start another Run"
        );
        LiveRunRegistry::release_success_if_new_request(&session, None, 99);
        assert!(
            !LiveRunRegistry::is_occupied(&session),
            "a new prompt may start a fresh Run after success"
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn insert_of_already_completed_success_seals_fingerprint_tombstone() {
        let _registry = lock_live_registry_for_test();
        let session = format!("fast-success-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let handle = dummy_handle("fast-run");
        handle.set_request_fingerprint(7);
        handle.completed.store(true, Ordering::Release);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(handle)
            .expect("insert");
        assert!(
            LiveRunRegistry::is_occupied(&session),
            "a Run that finished before insert must not be pruned as a free slot"
        );
        LiveRunRegistry::release_success_if_new_request(&session, None, 7);
        assert!(
            LiveRunRegistry::is_occupied(&session),
            "retrying the same request after a fast success must not start another Run"
        );
        LiveRunRegistry::release_success_if_new_request(&session, None, 8);
        assert!(
            !LiveRunRegistry::is_occupied(&session),
            "a new prompt may start a fresh Run after fast success"
        );
        LiveRunRegistry::clear();
    }

