    #[test]
    fn fresh_replacement_predicate_only_accepts_dead_or_client_only_generations() {
        // A connected native-tool run still owns its downstream response and
        // must not be cancelled merely because a different prompt arrived.
        let (connected_tx, connected_rx) = mpsc::channel(1);
        let connected = Arc::new(CursorLiveRunHandle {
            run_id: "connected-native".into(),
            command_tx: connected_tx,
            pending: Arc::new(Mutex::new(vec![pending_exec(1, "read-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(1)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let _connected_rx = connected_rx;
        assert!(!connected.is_replaceable_for_fresh_request());

        // Client-only batches intentionally tear down the BiDi worker after
        // exposing the tool, so a fresh turn must be allowed to take over.
        let (client_tx, client_rx) = mpsc::channel(1);
        let client_only = Arc::new(CursorLiveRunHandle {
            run_id: "client-only".into(),
            command_tx: client_tx,
            pending: Arc::new(Mutex::new(vec![pending_client_only(2, "workflow-1")])),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(2)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let _client_rx = client_rx;
        assert!(client_only.is_replaceable_for_fresh_request());

        // A cancellation signal is a generation-bound stale marker even when
        // the control channel is still winding down.
        let (cancel_tx, cancel_rx) = mpsc::channel(1);
        let cancelled = Arc::new(CursorLiveRunHandle {
            run_id: "cancelled".into(),
            command_tx: cancel_tx,
            pending: Arc::new(Mutex::new(Vec::new())),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(3)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        let _cancel_rx = cancel_rx;
        assert!(cancelled.is_replaceable_for_fresh_request());
    }

    #[test]
    fn fresh_replacement_claim_rechecks_consumer_state_at_commit() {
        let _registry = lock_live_registry_for_test();
        let session = format!("fresh-claim-fence-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let (command_tx, command_rx) = mpsc::channel(1);
        // Keep the command channel open while the claim is tested. A closed
        // receiver is itself a replaceable-generation signal and would mask
        // the consumer reattachment fence this regression covers.
        let _command_rx_guard = command_rx;
        let handle = Arc::new(CursorLiveRunHandle {
            run_id: "reattached-generation".into(),
            command_tx,
            pending: Arc::new(Mutex::new(Vec::new())),
            terminal_error: Arc::new(Mutex::new(None)),
            completed: Arc::new(AtomicBool::new(false)),
            cancel_requested: Arc::new(AtomicBool::new(false)),
            resume_in_flight: Arc::new(ResumeAdmission::default()),
            request_fingerprint: Arc::new(AtomicU64::new(1)),
            consumer_gone: Arc::new(AtomicBool::new(false)),
        });
        handle.consumer_gone.store(true, Ordering::Release);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(Arc::clone(&handle))
            .expect("insert run");

        let observed = LiveRunRegistry::replaceable_running_generation(&session, None)
            .expect("orphan generation should be observed");
        assert_eq!(observed, "reattached-generation");
        // The original consumer reattached after the waiter snapshot. The
        // claim must refuse to cancel this now-healthy generation.
        handle.consumer_gone.store(false, Ordering::Release);
        assert!(matches!(
            LiveRunRegistry::claim_replacement_for_fresh_request(&session, None, &observed),
            LiveReplacementClaim::Conflict
        ));
        assert_eq!(
            LiveRunRegistry::running_generation(&session, None).as_deref(),
            Some("reattached-generation")
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn fresh_replacement_lookup_handles_hidden_cancelled_generation() {
        let _registry = lock_live_registry_for_test();
        let session = format!("hidden-cancelled-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let (handle, _command_rx) = connected_dummy_handle("hidden-cancelled-generation");
        handle.set_request_fingerprint(11);
        handle.cancel_requested.store(true, Ordering::Release);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(Arc::clone(&handle))
            .expect("insert hidden generation");

        assert!(
            LiveRunRegistry::get_run(&session, None).is_none(),
            "cancel-requested handles stay hidden from attach/resume"
        );
        let replacement = LiveRunRegistry::replaceable_run_for_fresh_request(&session, None, 22)
            .expect("a different fresh operation must see the exact hidden generation");
        assert_eq!(replacement.run_id(), "hidden-cancelled-generation");
        assert!(
            LiveRunRegistry::replaceable_run_for_fresh_request(&session, None, 11).is_none(),
            "an identical retry must not replace its own hidden generation"
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn fresh_start_waits_on_hidden_identical_generation_but_can_claim_different_one() {
        let _registry = lock_live_registry_for_test();
        let session = format!("hidden-start-wait-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let (handle, _command_rx) = connected_dummy_handle("hidden-start-generation");
        handle.set_request_fingerprint(11);
        handle.cancel_requested.store(true, Ordering::Release);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(Arc::clone(&handle))
            .expect("insert hidden generation");

        assert!(
            LiveRunRegistry::hidden_running_requires_wait(&session, None),
            "an incomplete hidden driver needs a transition wait"
        );
        assert!(
            super::super::live_start_should_wait_without_admission(&session, None, 11),
            "an identical retry must wait for the hidden generation to publish replay/terminal state"
        );
        assert!(
            !super::super::live_start_should_wait_without_admission(&session, None, 22),
            "a different fresh operation may reacquire capacity and claim the replaceable generation"
        );
        store_terminal_error(&handle.terminal_error, "Cursor live run cancelled");
        assert!(
            !LiveRunRegistry::hidden_running_requires_wait(&session, None),
            "once a terminal outcome is published, the next loop must reacquire and probe it"
        );
        assert!(
            !super::super::live_start_should_wait_without_admission(&session, None, 11),
            "a terminal hidden generation must be probed instead of waited forever"
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn claim_replacement_cancel_requested_is_generation_bound() {
        let _registry = lock_live_registry_for_test();
        let session = format!("dying-bound-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let handle = dummy_handle("dying-generation");
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(Arc::clone(&handle))
            .expect("insert dying run");
        handle.cancel();

        assert!(
            matches!(
                LiveRunRegistry::claim_replacement_for_run(&session, None, "other-generation"),
                LiveReplacementClaim::Conflict
            ),
            "a stale waiter must not take over a cancel-requested generation it did not observe"
        );
        assert!(
            LiveRunRegistry::is_occupied(&session),
            "a mismatched claim must leave the dying generation in place"
        );

        let LiveReplacementClaim::Reserved {
            reservation,
            superseded: Some(superseded),
        } = LiveRunRegistry::claim_replacement_for_run(&session, None, "dying-generation")
        else {
            panic!("the matching cancel-requested generation must be replaceable");
        };
        assert_eq!(superseded.run_id(), "dying-generation");
        assert!(LiveRunRegistry::is_starting_run(&session, None));
        reservation.release();
        LiveRunRegistry::clear();
    }

    #[test]
    fn fresh_request_never_replaces_a_run_when_cancel_is_ambiguous() {
        let _registry = lock_live_registry_for_test();
        let session = format!("fresh-amb-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let handle = dummy_handle("amb-generation");
        handle.set_request_fingerprint(11);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(Arc::clone(&handle))
            .expect("insert");
        let LiveReplacementClaim::Reserved {
            reservation,
            superseded: Some(superseded),
        } = LiveRunRegistry::claim_replacement_for_run(&session, None, "amb-generation")
        else {
            panic!("matching generation must be claimable");
        };
        reservation.protect_on_drop();
        let error = CursorError::new(
            409,
            "Cursor live run ended in an ambiguous upstream state; replacement blocked: acceptance is ambiguous",
            None,
        );
        let error =
            match finish_replacement_after_cancel(reservation, superseded, false, Err(error)) {
                Err(error) => error,
                Ok(_) => panic!("an unresolved old Run must block a replacement"),
            };
        assert_eq!(error.status, 409);
        assert!(
            LiveRunRegistry::is_ambiguous_run(&session, None),
            "the slot must stay sealed until the old Run's acceptance is resolved"
        );
        assert!(
            LiveRunRegistry::is_ambiguous_for_operation(&session, None, 11),
            "the unresolved old operation must remain fail-closed"
        );
        assert!(
            !LiveRunRegistry::is_ambiguous_for_operation(&session, None, 22),
            "a later operation must not inherit the old operation's 409"
        );
        let replacement =
            LiveRunRegistry::claim_ambiguous_release_for_new_operation(&session, None, 22)
                .expect("a different operation must be able to replace a scoped tombstone");
        replacement.release();
        assert!(LiveRunRegistry::running_generation(&session, None).is_none());
        LiveRunRegistry::clear();
    }

