    #[test]
    fn client_only_anthropic_name_rejects_lifecycle_spoof() {
        let allowed = BTreeSet::from(["spawn_subagent".to_string()]);
        assert_eq!(
            client_only_anthropic_name("spawn_subagent", "claude-local", Some(&allowed)).as_deref(),
            Some("spawn_subagent")
        );
        assert_eq!(
            client_only_anthropic_name(
                "mcp_claude-local_spawn_subagent",
                "claude-local",
                Some(&allowed)
            )
            .as_deref(),
            Some("spawn_subagent"),
            "Cursor MCP catalog name must become grok-build spawn_subagent"
        );
        assert_eq!(
            client_only_anthropic_name(
                "mcp__claude-local__spawn_subagent",
                "claude-local",
                Some(&allowed)
            )
            .as_deref(),
            Some("spawn_subagent")
        );
        assert_eq!(
            client_only_anthropic_name(
                "claude-local/spawn_subagent",
                "claude-local",
                Some(&allowed)
            )
            .as_deref(),
            Some("spawn_subagent")
        );
        assert_eq!(
            client_only_anthropic_name("evil/spawn_subagent", "evil", Some(&allowed)),
            None,
            "prefix stripping must not promote a foreign MCP spawn"
        );
        assert_eq!(
            client_only_anthropic_name("spawn_subagent", "evil", Some(&allowed)),
            None,
            "external provider cannot impersonate claude-local spawn_subagent"
        );
        assert_eq!(
            client_only_anthropic_name("spawn_subagent", "claude-local", None),
            None,
            "allowed=None must not translate lifecycle tools"
        );
        assert_eq!(
            client_only_anthropic_name("web_search", "", None),
            None,
            "allowed=None must not invent XML/hosted web_search"
        );
        assert_eq!(
            client_only_anthropic_name("web_fetch", "claude-local", None),
            None,
            "allowed=None must not invent web_fetch even with claude-local provider"
        );
        assert_eq!(
            client_only_anthropic_name("enter_plan_mode", "", None),
            None
        );
        assert_eq!(
            client_only_anthropic_name("Workflow", "claude-local", None),
            None,
            "allowed=None must not invent Workflow via MCP provider bypass"
        );
        let aliases = BTreeSet::from(["task".to_string(), "Agent".to_string(), "Task".to_string()]);
        assert_eq!(
            client_only_anthropic_name("spawn_subagent", "claude-local", Some(&aliases)),
            None
        );
        assert_eq!(
            client_only_anthropic_name("task", "claude-local", Some(&aliases)),
            None,
            "internal task alias is not a reserved lifecycle MCP name"
        );
    }

    #[test]
    fn client_only_anthropic_name_maps_advertised_mcp_task_to_client_task_tool() {
        // Claude Code advertises Task; the MCP catalog exposes it as
        // mcp_claude-local_Task. Model calls against that catalog entry must
        // come back as Claude Code Task tool_use, or the advertised tool
        // errors as unsupported on every call.
        let allowed = BTreeSet::from(["Task".to_string(), "Workflow".to_string()]);
        for (mapped, provider) in [
            ("mcp_claude-local_Task", "claude-local"),
            ("mcp__claude-local__Task", "claude-local"),
            ("Task", "claude-local"),
            ("mcp_claude-local_Task", ""),
        ] {
            assert_eq!(
                client_only_anthropic_name(mapped, provider, Some(&allowed)).as_deref(),
                Some("Task"),
                "{mapped} (provider={provider:?}) must map back to Claude Code Task"
            );
        }
        assert_eq!(
            client_only_anthropic_name("Task", "", Some(&allowed)),
            None,
            "bare Task without an MCP qualifier is Cursor native Task — only the native-Task branch may translate it"
        );
        assert_eq!(
            client_only_anthropic_name("mcp_claude-local_Task", "evil", Some(&allowed)),
            None,
            "foreign providers cannot impersonate claude-local Task"
        );
        assert_eq!(
            client_only_anthropic_name("mcp_claude-local_Task", "claude-local", None),
            None,
            "allowed=None must not invent Task"
        );
        // grok-build never advertises Task on MCP, but if a mixed allowlist
        // ever produced this call the client's real task tool wins.
        let grok = BTreeSet::from(["spawn_subagent".to_string()]);
        assert_eq!(
            client_only_anthropic_name("mcp_claude-local_Task", "claude-local", Some(&grok))
                .as_deref(),
            Some("spawn_subagent")
        );
        let agent_only = BTreeSet::from(["Agent".to_string()]);
        assert_eq!(
            client_only_anthropic_name("mcp_claude-local_Agent", "claude-local", Some(&agent_only))
                .as_deref(),
            Some("Agent")
        );
        assert_eq!(
            client_only_anthropic_name("Agent", "", Some(&agent_only)).as_deref(),
            Some("Agent"),
            "Agent has no Cursor-native counterpart and may arrive from XML without provider metadata"
        );
    }

    #[test]
    fn client_only_anthropic_name_maps_fable_workflow_to_grok_workflow() {
        let allowed = BTreeSet::from(["workflow".to_string(), "skill".to_string()]);
        for mapped in [
            "Workflow",
            "workflow",
            "claude-local/Workflow",
            "mcp_claude-local_Workflow",
            "mcp_claude-local_workflow",
            "mcp__claude-local__Workflow",
        ] {
            assert_eq!(
                client_only_anthropic_name(mapped, "claude-local", Some(&allowed)).as_deref(),
                Some("workflow"),
                "{mapped} must steal as the exact grok-cli name"
            );
        }
        assert_eq!(
            client_only_anthropic_name("Skill", "claude-local", Some(&allowed)).as_deref(),
            Some("skill")
        );
        let grep_allowed = BTreeSet::from(["grep".to_string()]);
        assert_eq!(
            client_only_anthropic_name(
                "mcp_claude-local_Grep",
                "claude-local",
                Some(&grep_allowed)
            ),
            None,
            "case folding must not turn Cursor Grep into grok grep"
        );
        assert!(
            client_only_anthropic_name("Workflow", "claude-local", Some(&allowed)).as_deref()
                != Some("Workflow"),
            "must not emit Claude Code Workflow when grok advertised workflow"
        );
    }

    #[tokio::test]
    async fn mcp_workflow_tool_call_started_exposes_client_only() {
        use super::super::connect::encode_connect_frame;
        use super::super::proto::{
            AgentServerMessage, InteractionUpdate, McpArgs, McpToolCall, ToolCall, ToolCallStarted,
        };
        use prost::Message;

        let mut full = Vec::new();
        AgentServerMessage {
            conversation_checkpoint_update: None,
            interaction_update: Some(InteractionUpdate {
                heartbeat: None,
                text_delta: None,
                tool_call_started: Some(ToolCallStarted {
                    call_id: "mcp-wf-1".into(),
                    model_call_id: "model-1".into(),
                    tool_call: Some(ToolCall {
                        mcp_tool_call: Some(McpToolCall {
                            args: Some(McpArgs {
                                name: "Workflow".into(),
                                tool_name: "Workflow".into(),
                                tool_call_id: "mcp-wf-1".into(),
                                provider_identifier: "claude-local".into(),
                                args: {
                                    let mut m = std::collections::HashMap::new();
                                    m.insert("name".into(), br#""deep-research""#.to_vec());
                                    m
                                },
                            }),
                        }),
                        ..Default::default()
                    }),
                }),
                tool_call_completed: None,
                thinking_delta: None,
                thinking_completed: None,
                token_delta: None,
                partial_tool_call: None,
                tool_call_delta: None,
                turn_ended: None,
            }),
            exec_server_message: None,
            kv_server_message: None,
            interaction_query: None,
        }
        .encode(&mut full)
        .unwrap();
        let framed = encode_connect_frame(full, 0);
        let mut decoder = super::super::connect::ConnectFrameDecoder::new();
        let frames = decoder.push(&framed).unwrap();

        let (request_tx, _request_rx) = mpsc::channel(4);
        let outbound = ClientOutbound::Bidi(request_tx);
        let (event_tx, mut event_rx) = mpsc::channel(8);
        let mut sink = Some(event_tx);
        let mut deferred = VecDeque::new();
        let mut segment_replay = SegmentReplayLog::default();
        let mut pending = PendingExecState::default();
        let pending_shared = Arc::new(Mutex::new(Vec::new()));
        let mut kv_blobs = HashMap::new();
        let mut latest_checkpoint = None;
        let terminal_error = Arc::new(Mutex::new(None));
        let mut saw_text = false;
        let mut useful = false;
        let mut logical = LogicalToolTracker::default();
        let mut last_progress = Instant::now();
        let allowed = BTreeSet::from(["Workflow".to_string()]);
        let mut xml_parser = CursorToolUseXmlParser::new(Some(allowed.clone()));

        let cont = process_live_frame(
            frames.into_iter().next().unwrap(),
            &outbound,
            &mut sink,
            &mut deferred,
            &mut segment_replay,
            &mut pending,
            &pending_shared,
            &mut kv_blobs,
            &mut latest_checkpoint,
            &terminal_error,
            Some(&allowed),
            &mut saw_text,
            &mut useful,
            &mut logical,
            &mut last_progress,
            Duration::from_millis(50),
            &mut xml_parser,
            None,
        )
        .await;
        assert!(!cont, "MCP Workflow must end BiDi segment");
        let event = event_rx.recv().await.expect("NativeToolBatch");
        match event {
            Ok(LiveRunEvent::NativeToolBatch(tools)) => {
                assert_eq!(tools.len(), 1);
                assert_eq!(tools[0].name, "Workflow");
                assert_eq!(
                    tools[0].input.get("name").and_then(|v| v.as_str()),
                    Some("deep-research")
                );
                assert!(
                    tools[0].input.get("provider_identifier").is_none(),
                    "Workflow Anthropic input must not include provider_identifier"
                );
            }
            other => panic!("expected NativeToolBatch, got {other:?}"),
        }
    }

    fn mcp_task_started_frame(call_id: &str) -> super::super::connect::ConnectFrame {
        use super::super::connect::encode_connect_frame;
        use super::super::proto::{
            AgentServerMessage, InteractionUpdate, McpArgs, McpToolCall, ToolCall, ToolCallStarted,
        };
        use prost::Message;

        let mut full = Vec::new();
        AgentServerMessage {
            interaction_update: Some(InteractionUpdate {
                tool_call_started: Some(ToolCallStarted {
                    call_id: call_id.into(),
                    model_call_id: "model-task".into(),
                    tool_call: Some(ToolCall {
                        mcp_tool_call: Some(McpToolCall {
                            args: Some(McpArgs {
                                name: "Task".into(),
                                tool_name: "Task".into(),
                                tool_call_id: call_id.into(),
                                provider_identifier: "claude-local".into(),
                                args: {
                                    let mut m = std::collections::HashMap::new();
                                    m.insert("description".into(), br#""audit tests""#.to_vec());
                                    m.insert("prompt".into(), br#""run the audit""#.to_vec());
                                    m.insert("subagent_type".into(), br#""explore""#.to_vec());
                                    m
                                },
                            }),
                        }),
                        ..Default::default()
                    }),
                }),
                ..Default::default()
            }),
            ..Default::default()
        }
        .encode(&mut full)
        .unwrap();
        let framed = encode_connect_frame(full, 0);
        let mut decoder = super::super::connect::ConnectFrameDecoder::new();
        decoder.push(&framed).unwrap().into_iter().next().unwrap()
    }

    #[tokio::test]
    async fn mcp_task_tool_call_started_exposes_claude_task_client_only() {
        // The MCP catalog advertises `mcp_claude-local_Task` for Claude Code.
        // A model call against it must come back as a Claude Code `Task`
        // tool_use, or subagents error as unsupported on every call.
        let allowed = BTreeSet::from(["Task".to_string(), "Workflow".to_string()]);
        let (cont, event, pending) =
            drive_native_task_frame(mcp_task_started_frame("mcp-task-1"), Some(&allowed), None)
                .await;
        assert!(!cont, "MCP Task must expose ClientOnly and end the segment");
        match event.expect("NativeToolBatch") {
            Ok(LiveRunEvent::NativeToolBatch(tools)) => {
                assert_eq!(tools.len(), 1, "MCP Task must queue exactly once");
                assert_eq!(tools[0].name, "Task");
                assert_eq!(
                    tools[0].input.get("prompt").and_then(|v| v.as_str()),
                    Some("run the audit")
                );
                assert!(
                    tools[0].input.get("provider_identifier").is_none(),
                    "Task Anthropic input must not include provider_identifier"
                );
            }
            other => panic!("expected Task NativeToolBatch, got {other:?}"),
        }
        assert_eq!(
            pending.awaiting.len(),
            1,
            "exposed exec must await the client tool result exactly once"
        );
        assert!(pending.collecting.is_empty());
    }

    #[tokio::test]
    async fn mcp_task_with_turn_ctx_defers_and_queues_exactly_once() {
        // Live-driver path (turn_ctx present, exposure deferred): the
        // claude-local MCP Task is handled by the ClientOnly arm; the native
        // Task branch must skip it via the provider guard or the exec queues
        // twice and Claude Code sees duplicate tool_use ids.
        let allowed = BTreeSet::from(["Task".to_string()]);
        let request_context = RequestContext::default();
        let mut decode_failures = 0;
        let mut coalescer = LiveDeltaCoalescer::default();
        let mut post_tool_checkpoint = PostToolCheckpointEvidence::default();
        let mut turn = LiveTurnCtx {
            session_id: "sess-mcp-task",
            user_prompt: "spawn a subagent",
            compaction_mode: false,
            post_tool_checkpoint: &mut post_tool_checkpoint,
            request_context: &request_context,
            decode_failures: &mut decode_failures,
            coalescer: &mut coalescer,
            sand_empty_end: None,
        };
        let (cont, event, pending) = drive_native_task_frame(
            mcp_task_started_frame("mcp-task-2"),
            Some(&allowed),
            Some(&mut turn),
        )
        .await;
        assert!(cont, "deferred exposure keeps the segment running");
        assert!(
            event.is_none(),
            "exposure must wait for turn end: {event:?}"
        );
        assert_eq!(
            pending.awaiting.len() + pending.collecting.len(),
            1,
            "claude-local Task must not double-queue via the native-Task branch"
        );
        let exec = pending
            .collecting
            .first()
            .or_else(|| pending.awaiting.first())
            .expect("one pending exec");
        assert_eq!(exec.claude_name, "Task");
    }

