    #[tokio::test]
    async fn terminal_error_waits_behind_buffered_events_without_being_dropped() {
        let (tx, mut rx) = mpsc::channel(1);
        tx.send(Ok(LiveRunEvent::Cursor(
            CursorStreamEvent::OutputTokenDelta { tokens: 1 },
        )))
        .await
        .unwrap();
        let terminal_error = Arc::new(Mutex::new(None));
        let mut sink = Some(tx);

        report_terminal_error(
            &mut sink,
            &terminal_error,
            "Cursor completion is ambiguous".into(),
        )
        .await;

        assert!(rx.recv().await.is_some(), "buffered event");
        let terminal = tokio::time::timeout(Duration::from_secs(1), rx.recv())
            .await
            .expect("terminal event remained blocked")
            .expect("terminal event was dropped");
        assert!(
            matches!(terminal, Err(message) if message.contains("ambiguous")),
            "the original terminal cause must reach the SSE encoder"
        );
    }

    #[tokio::test]
    async fn deferred_live_events_are_bounded_between_segments() {
        let mut sink = None;
        let mut deferred = VecDeque::new();
        let mut segment_replay = SegmentReplayLog::default();
        for index in 0..MAX_DEFERRED_LIVE_EVENTS {
            assert!(
                emit_or_defer(
                    &mut sink,
                    &mut deferred,
                    &mut segment_replay,
                    Ok(LiveRunEvent::Cursor(CursorStreamEvent::OutputTokenDelta {
                        tokens: index as u64,
                    })),
                )
                .await
            );
        }
        assert!(
            !emit_or_defer(
                &mut sink,
                &mut deferred,
                &mut segment_replay,
                Ok(LiveRunEvent::Cursor(CursorStreamEvent::OutputTokenDelta {
                    tokens: u64::MAX,
                })),
            )
            .await,
            "the driver must fail closed instead of growing an unbounded deferred queue"
        );
        assert_eq!(deferred.len(), MAX_DEFERRED_LIVE_EVENTS);
    }

    /// Harness for the attach-with-replay regression tests: a live driver fed
    /// through a fake BiDi upstream, returning the handles needed to emit
    /// frames, receive downstream events, and issue driver commands.
    struct AttachReplayHarness {
        upstream_tx: mpsc::Sender<Result<Option<Bytes>, String>>,
        command_tx: mpsc::Sender<RunCommand>,
        event_rx: mpsc::Receiver<LiveEventResult>,
        completed: Arc<AtomicBool>,
        terminal_error: Arc<Mutex<Option<TerminalOutcome>>>,
    }

    fn spawn_attach_replay_driver(session: &str) -> AttachReplayHarness {
        spawn_attach_replay_driver_with_tools(session, BTreeSet::from(["Read".to_string()]))
    }

    fn spawn_attach_replay_driver_with_tools(
        session: &str,
        allowed_tool_names: BTreeSet<String>,
    ) -> AttachReplayHarness {
        let (upstream_tx, upstream_rx) = mpsc::channel::<Result<Option<Bytes>, String>>(16);
        let (request_tx, _request_rx) = mpsc::channel(8);
        let (command_tx, command_rx) = mpsc::channel(4);
        let (event_tx, event_rx) = mpsc::channel(32);
        let completed = Arc::new(AtomicBool::new(false));
        let terminal_error = Arc::new(Mutex::new(None));
        // `conversation::reset_for_test` intentionally serializes global
        // store replacement. Hold the same guard across creation and pin so
        // a parallel test cannot evict this fresh binding in between.
        let _store_guard = super::super::conversation::STORE_TEST_LOCK
            .lock()
            .unwrap_or_else(|poison| poison.into_inner());
        let conversation = super::super::conversation::get_or_create(session);
        let conversation_lease =
            super::super::conversation::pin(session, &conversation.conversation_id)
                .expect("pin test conversation");
        drop(_store_guard);
        let mut reconnect = test_reconnect_context();
        reconnect.session_id = session.to_string();
        reconnect.conversation_id = Some(conversation.conversation_id);
        let mut generation_permit = test_generation_permit();
        generation_permit._conversation_lease = Some(conversation_lease);
        tokio::spawn(drive_live_run(
            upstream_rx,
            upstream_tx.clone(),
            tokio::spawn(std::future::pending::<()>()),
            ClientOutbound::Bidi(request_tx),
            command_rx,
            event_tx,
            Arc::new(Mutex::new(Vec::new())),
            Arc::clone(&terminal_error),
            Arc::clone(&completed),
            Arc::new(AtomicBool::new(false)),
            Some(allowed_tool_names),
            session.into(),
            format!("{session}-run"),
            HashMap::new(),
            "attach replay prompt".into(),
            RequestContext::default(),
            reconnect,
            generation_permit,
        ));
        AttachReplayHarness {
            upstream_tx,
            command_tx,
            event_rx,
            completed,
            terminal_error,
        }
    }

    async fn send_text_delta(
        upstream_tx: &mpsc::Sender<Result<Option<Bytes>, String>>,
        text: &str,
    ) {
        let mut payload = Vec::new();
        proto::AgentServerMessage {
            conversation_checkpoint_update: None,
            interaction_update: Some(InteractionUpdate {
                heartbeat: None,
                text_delta: Some(TextDelta { text: text.into() }),
                ..Default::default()
            }),
            kv_server_message: None,
            interaction_query: None,
            exec_server_message: None,
        }
        .encode(&mut payload)
        .unwrap();
        upstream_tx
            .send(Ok(Some(encode_connect_frame(payload, 0))))
            .await
            .unwrap();
    }

    async fn attach_replay(
        command_tx: &mpsc::Sender<RunCommand>,
        fingerprint: u64,
    ) -> Result<mpsc::Receiver<LiveEventResult>, CursorError> {
        let (ack, ready) = oneshot::channel();
        command_tx
            .send(RunCommand::AttachReplay {
                ack,
                expected_fingerprint: fingerprint,
                fingerprint_source: Arc::new(AtomicU64::new(fingerprint)),
            })
            .await
            .expect("driver accepts commands");
        tokio::time::timeout(Duration::from_secs(2), ready)
            .await
            .expect("driver answers attach")
            .expect("attach ack not dropped")
    }

    #[tokio::test]
    async fn attach_replay_recovers_segment_after_consumer_drop() {
        // The 503 "already active" wedge: the original consumer vanished
        // mid-generation and an identical retry must take over the segment
        // with a full replay instead of bouncing until the run dies.
        let mut harness = spawn_attach_replay_driver("attach-after-drop");
        send_text_delta(&harness.upstream_tx, "first chunk").await;
        let first = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("text delta flushed")
            .expect("stream open")
            .expect("no error");
        assert!(matches!(
            &first,
            LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }) if text == "first chunk"
        ));
        drop(harness.event_rx);

        let mut attached = attach_replay(&harness.command_tx, 7)
            .await
            .expect("identical retry attaches once the original consumer is gone");
        let replayed = tokio::time::timeout(Duration::from_secs(2), attached.recv())
            .await
            .expect("replayed prefix arrives")
            .expect("attached stream open")
            .expect("no error");
        assert!(
            matches!(
                &replayed,
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }) if text == "first chunk"
            ),
            "the attached retry must receive the already-delivered prefix: {replayed:?}"
        );

        // The attached channel is adopted as the live sink: later upstream
        // deltas continue on it.
        send_text_delta(&harness.upstream_tx, "second chunk").await;
        let live = tokio::time::timeout(Duration::from_secs(2), attached.recv())
            .await
            .expect("live continuation arrives")
            .expect("attached stream still open")
            .expect("no error");
        assert!(
            matches!(
                &live,
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }) if text == "second chunk"
            ),
            "the attached retry must keep streaming the rest of the segment: {live:?}"
        );
        assert!(!harness.completed.load(Ordering::Acquire));
    }

    #[tokio::test]
    async fn attach_replay_steals_from_a_still_open_original_consumer() {
        // grok-build retries 503 sequentially with the same x-grok-req-id after
        // it has already abandoned the previous HTTP attempt. That attempt's
        // SSE body can still look "alive" for seconds (proxy buffering, delayed
        // TCP close). Rejecting attach as busy is what produced the 503 storm:
        // grok-build treats 503 as transient overload and retries 2s/4s/8s
        // while the Cursor run keeps the slot for the whole generation.
        // Same-fingerprint attach must steal the sink; last retry wins.
        let mut harness = spawn_attach_replay_driver("attach-steal-alive");
        send_text_delta(&harness.upstream_tx, "held by the original consumer").await;
        let _first = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("text delta flushed")
            .expect("stream open")
            .expect("no error");

        let mut attached = attach_replay(&harness.command_tx, 7)
            .await
            .expect("same-fingerprint retry must steal, not 503, while the old SSE is half-open");
        let replayed = tokio::time::timeout(Duration::from_secs(2), attached.recv())
            .await
            .expect("stolen consumer gets the prefix")
            .expect("attached stream open")
            .expect("no error");
        assert!(
            matches!(
                &replayed,
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text })
                    if text == "held by the original consumer"
            ),
            "stolen attach must replay the already-delivered prefix: {replayed:?}"
        );

        send_text_delta(&harness.upstream_tx, "after steal").await;
        let live = tokio::time::timeout(Duration::from_secs(2), attached.recv())
            .await
            .expect("live continuation after steal")
            .expect("attached stream still open")
            .expect("no error");
        assert!(
            matches!(
                &live,
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }) if text == "after steal"
            ),
            "the stolen retry must keep the live segment: {live:?}"
        );
        assert!(
            tokio::time::timeout(Duration::from_millis(200), harness.event_rx.recv())
                .await
                .ok()
                .flatten()
                .is_none(),
            "the abandoned original consumer must not keep receiving after steal"
        );
    }

    #[tokio::test]
    async fn simultaneous_identical_retry_storm_all_replays_the_prefix() {
        // A client can fan out many retries after every attempt receives the
        // same transient 503. They all identify the same logical operation,
        // so none may start another upstream Run or bounce as busy. Each
        // waiter gets the recorded prefix; the last attach becomes the sole
        // live sink for subsequent deltas.
        const RETRIES: usize = 64;
        let mut harness = spawn_attach_replay_driver("attach-retry-storm");
        send_text_delta(&harness.upstream_tx, "stable prefix").await;
        let first = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("initial prefix flushed")
            .expect("initial stream open")
            .expect("initial prefix is not an error");
        assert!(matches!(
            first,
            LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { ref text })
                if text == "stable prefix"
        ));

        let mut waiters = tokio::task::JoinSet::new();
        for _ in 0..RETRIES {
            let command_tx = harness.command_tx.clone();
            waiters.spawn(async move { attach_replay(&command_tx, 7).await });
        }

        let mut attached = Vec::with_capacity(RETRIES);
        while let Some(result) = waiters.join_next().await {
            attached.push(
                result
                    .expect("attach task")
                    .expect("same-fingerprint retry must attach without a 503"),
            );
        }
        assert_eq!(attached.len(), RETRIES);
        for events in &mut attached {
            let replayed = tokio::time::timeout(Duration::from_secs(2), events.recv())
                .await
                .expect("replayed prefix arrives")
                .expect("attached stream contains the prefix")
                .expect("replayed prefix is not an error");
            assert!(matches!(
                replayed,
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { ref text })
                    if text == "stable prefix"
            ));
        }

        send_text_delta(&harness.upstream_tx, "one live continuation").await;
        let mut live_continuations = 0;
        for events in &mut attached {
            match tokio::time::timeout(Duration::from_secs(2), events.recv())
                .await
                .expect("superseded attach closes or receives the continuation")
            {
                Some(Ok(LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text })))
                    if text == "one live continuation" =>
                {
                    live_continuations += 1;
                }
                None => {}
                other => panic!("unexpected post-attach event: {other:?}"),
            }
        }
        assert_eq!(
            live_continuations, 1,
            "exactly one retry may own the live continuation after the retry storm"
        );
        assert!(
            !harness.completed.load(Ordering::Acquire),
            "all retries must remain attached to one upstream generation"
        );

        harness
            .command_tx
            .send(RunCommand::Cancel { ack: None })
            .await
            .expect("cancel retry-storm driver");
        tokio::time::timeout(Duration::from_secs(2), async {
            while !harness.completed.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("retry-storm driver terminates");
    }

    #[tokio::test]
    async fn attach_replay_reproduces_exposed_native_tool_batch() {
        // Segment already closed by a NativeToolBatch handoff (the exact state
        // from the grok-build 503 storms: run Running, waiting on tool
        // results, retry same fingerprint). Replay must reproduce the batch
        // and end the attached stream exactly where the original ended.
        let mut harness = spawn_attach_replay_driver("attach-tool-batch");
        let mut payload = Vec::new();
        proto::AgentServerMessage {
            exec_server_message: Some(ExecServerMessage {
                id: 1,
                exec_id: Some("read-exec".into()),
                read_args: Some(ExecReadArgs {
                    path: "/tmp/input.txt".into(),
                    tool_call_id: "read-call".into(),
                    offset: None,
                    limit: None,
                }),
                ..Default::default()
            }),
            ..Default::default()
        }
        .encode(&mut payload)
        .unwrap();
        harness
            .upstream_tx
            .send(Ok(Some(encode_connect_frame(payload, 0))))
            .await
            .unwrap();
        let original = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("native tool exposed")
            .expect("stream open")
            .expect("no error");
        let LiveRunEvent::NativeToolBatch(original_tools) = original else {
            panic!("expected native tool batch, got {original:?}");
        };
        assert!(!harness.completed.load(Ordering::Acquire));

        let mut attached = attach_replay(&harness.command_tx, 7)
            .await
            .expect("retry attaches to the tool-result wait state");
        let replayed = tokio::time::timeout(Duration::from_secs(2), attached.recv())
            .await
            .expect("replayed batch arrives")
            .expect("attached stream open")
            .expect("no error");
        let LiveRunEvent::NativeToolBatch(replayed_tools) = replayed else {
            panic!("expected replayed native tool batch, got {replayed:?}");
        };
        assert_eq!(replayed_tools.len(), original_tools.len());
        assert_eq!(replayed_tools[0].tool_use_id, original_tools[0].tool_use_id);
        assert_eq!(replayed_tools[0].name, original_tools[0].name);
        // The segment closed at the batch; the attached stream must end there
        // too so the retry's HTTP response terminates like the original.
        assert!(
            tokio::time::timeout(Duration::from_secs(2), attached.recv())
                .await
                .expect("attached stream must close after replaying a closed segment")
                .is_none(),
            "no events may follow the replayed segment boundary"
        );
        assert!(
            !harness.completed.load(Ordering::Acquire),
            "the run must stay resumable for tool results after an attach"
        );
    }

    #[tokio::test]
    async fn driver_does_not_mark_client_only_handoff_ambiguous() {
        // Client-only MCP tools intentionally end the current Anthropic
        // segment immediately after publishing their batch. The driver macro
        // must recognize that boundary instead of appending a spurious
        // "completion is ambiguous" terminal outcome (which otherwise leaves
        // the session stuck behind repeated 503s before tool_result resume).
        let session = format!("client-only-handoff-driver-{}", uuid::Uuid::new_v4());
        let mut harness = spawn_attach_replay_driver_with_tools(
            &session,
            BTreeSet::from(["spawn_subagent".to_string()]),
        );
        // Native Cursor Task is stolen by the Claude-local
        // `spawn_subagent` adapter and exposes immediately even while the
        // live driver owns a turn context.
        let frame = native_task_started_frame("driver-native-task", "run the child", Some(false));
        let wire = super::super::connect::encode_connect_frame(frame.payload, frame.flags);
        harness
            .upstream_tx
            .send(Ok(Some(wire)))
            .await
            .expect("send client-only frame");

        let event = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("client-only batch was not exposed")
            .expect("driver closed before exposing client-only batch")
            .expect("client-only handoff must not emit an error");
        assert!(matches!(
            event,
            LiveRunEvent::NativeToolBatch(tools)
                if tools.len() == 1 && tools[0].name == "spawn_subagent"
        ));

        // Allow the frame-processing macro to run its post-return terminal
        // check. A valid handoff must leave the run resumable and error-free.
        tokio::time::sleep(Duration::from_millis(75)).await;
        let terminal = harness
            .terminal_error
            .lock()
            .unwrap_or_else(|error| error.into_inner())
            .clone();
        assert!(
            terminal.is_none(),
            "client-only segment handoff must not create a terminal ambiguity: {terminal:?}"
        );
        assert!(
            harness.completed.load(Ordering::Acquire),
            "client-only handoff is a completed downstream segment; the driver may seal cleanly"
        );
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)]
    async fn completed_turn_with_gone_consumer_seals_replayable_success() {
        // The other half of the 503/409 wedge: the consumer disconnects and
        // the model then finishes the turn. This must seal Succeeded with the
        // recorded segment — not a 90s Ambiguous tombstone — so the identical
        // retry receives the original response.
        let _registry = lock_live_registry_for_test();
        let session = "completed-orphan-replay";
        LiveRunRegistry::clear();
        let registry_handle = dummy_handle(&format!("{session}-run"));
        registry_handle.set_request_fingerprint(7);
        LiveRunRegistry::reserve(session)
            .expect("reserve")
            .insert(Arc::clone(&registry_handle))
            .expect("insert running");

        let mut harness = spawn_attach_replay_driver(session);
        send_text_delta(&harness.upstream_tx, "the answer").await;
        let first = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("text delta flushed")
            .expect("stream open")
            .expect("no error");
        assert!(matches!(
            &first,
            LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }) if text == "the answer"
        ));
        drop(harness.event_rx);

        let mut turn_payload = Vec::new();
        proto::AgentServerMessage {
            interaction_update: Some(InteractionUpdate {
                turn_ended: Some(TurnEnded {
                    output_tokens: Some(3),
                    ..Default::default()
                }),
                ..Default::default()
            }),
            ..Default::default()
        }
        .encode(&mut turn_payload)
        .expect("encode turn_ended");
        harness
            .upstream_tx
            .send(Ok(Some(encode_connect_frame(turn_payload, 0))))
            .await
            .expect("send turn_ended");
        // turn_ended is held until Connect END makes it authoritative.
        harness
            .upstream_tx
            .send(Ok(Some(encode_connect_frame(
                Vec::new(),
                super::super::connect::FLAG_END,
            ))))
            .await
            .expect("send END");

        // Driver must terminate as a sealed success, not linger or tombstone.
        for _ in 0..100 {
            if harness.completed.load(Ordering::Acquire) {
                break;
            }
            tokio::time::sleep(Duration::from_millis(20)).await;
        }
        assert!(
            harness.completed.load(Ordering::Acquire),
            "completed turn with a gone consumer must still finish the driver"
        );
        assert!(
            !LiveRunRegistry::is_ambiguous_run(session, None),
            "observed completion must not be sealed as ambiguous"
        );

        let LiveSlotClaim::CompletedReplay(events) =
            LiveRunRegistry::try_claim_run_for_operation(session, None, 7)
        else {
            panic!("identical retry must receive the retained response");
        };
        assert!(
            matches!(
                events.first(),
                Some(LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text })) if text == "the answer"
            ),
            "replay must start with the delivered text: {events:?}"
        );
        assert!(
            matches!(
                events.last(),
                Some(LiveRunEvent::Cursor(CursorStreamEvent::End))
            ),
            "replay must end with the Anthropic terminal End: {events:?}"
        );

        // A different operation must not receive this response — it releases
        // the tombstone and claims the slot as a fresh run instead.
        let LiveSlotClaim::Reserved(reservation) =
            LiveRunRegistry::try_claim_run_for_operation(session, None, 8)
        else {
            panic!("a new operation must release the replay tombstone and reserve");
        };
        reservation.release();
        LiveRunRegistry::clear();
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)]
    async fn starting_running_succeeded_race_replays_to_identical_waiter() {
        // Reproduce the narrow admission race behind the post-/compact 503
        // storm: the retry observes Starting, while the original open becomes
        // Running and completes before the next registry poll. The terminal
        // replay must survive both transitions.
        let _registry = lock_live_registry_for_test();
        let session = format!("starting-running-success-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let body: crate::anthropic::schema::MessagesRequest =
            serde_json::from_value(serde_json::json!({
                "model": "cursor-grok-4.6-xhigh-fast",
                "stream": true,
                "messages": [{"role": "user", "content": "same compact retry"}]
            }))
            .unwrap();
        let fingerprint =
            live_request_fingerprint(&serde_json::to_vec(&body.messages).unwrap_or_default());
        let mut reservation = LiveRunRegistry::reserve(&session).expect("Starting reservation");
        reservation.set_operation_fingerprint(fingerprint);

        let transition = async {
            tokio::time::sleep(Duration::from_millis(40)).await;
            let handle = dummy_handle("fast-terminal-generation");
            handle.set_request_fingerprint(fingerprint);
            reservation
                .insert(Arc::clone(&handle))
                .expect("Starting becomes Running");
            LiveRunRegistry::seal_success_if(
                &session,
                "fast-terminal-generation",
                Some(Arc::new(vec![
                    LiveRunEvent::Cursor(CursorStreamEvent::TextDelta {
                        text: "compacted".into(),
                    }),
                    LiveRunEvent::Cursor(CursorStreamEvent::End),
                ])),
            );
            handle.completed.store(true, Ordering::Release);
        };
        let wait = super::super::await_live_run_resume(
            &session,
            None,
            &body,
            "msg_starting_running_success".into(),
            "cursor-grok-4.6-xhigh-fast".into(),
            1,
            None,
            true,
        );
        let (outcome, ()) = tokio::join!(wait, transition);

        let super::super::LiveResumeOutcome::Resumed(mut events) = outcome else {
            panic!("identical waiter must receive the Succeeded replay across the race");
        };
        assert!(matches!(
            events.recv().await,
            Some(Ok(LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text })))
                if text == "compacted"
        ));
        assert!(matches!(
            events.recv().await,
            Some(Ok(LiveRunEvent::Cursor(CursorStreamEvent::End)))
        ));
        assert!(events.recv().await.is_none());
        LiveRunRegistry::clear();
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)]
    async fn different_fingerprint_waiter_claims_slot_after_old_run_succeeds() {
        // A genuinely new turn must wait while the old connected generation
        // is healthy, then atomically claim the slot when that exact Run seals
        // success. It must not inherit an "already active" 503 from the
        // Running -> Succeeded handoff.
        let _registry = lock_live_registry_for_test();
        let session = format!("different-fingerprint-wait-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let body: crate::anthropic::schema::MessagesRequest =
            serde_json::from_value(serde_json::json!({
                "model": "cursor-grok-4.6-xhigh-fast",
                "stream": true,
                "messages": [{"role": "user", "content": "the next independent turn"}]
            }))
            .unwrap();
        let next_fingerprint =
            live_request_fingerprint(&serde_json::to_vec(&body.messages).unwrap_or_default());
        let (old, _command_rx_guard) = connected_dummy_handle("old-connected-generation");
        old.set_request_fingerprint(next_fingerprint ^ u64::MAX);
        LiveRunRegistry::reserve(&session)
            .expect("reserve old generation")
            .insert(Arc::clone(&old))
            .expect("insert old generation");

        let complete_old = async {
            tokio::time::sleep(Duration::from_millis(75)).await;
            LiveRunRegistry::seal_success_if(&session, "old-connected-generation", None);
            old.completed.store(true, Ordering::Release);
        };
        let wait = super::super::await_live_run_resume(
            &session,
            None,
            &body,
            "msg_next_turn".into(),
            "cursor-grok-4.6-xhigh-fast".into(),
            1,
            None,
            true,
        );
        let (outcome, ()) = tokio::join!(wait, complete_old);

        let super::super::LiveResumeOutcome::Free(Some(reservation)) = outcome else {
            panic!("new operation must atomically reserve after the old Run succeeds");
        };
        assert!(LiveRunRegistry::is_starting_run(&session, None));
        reservation.release();
        assert!(!LiveRunRegistry::is_occupied_run(&session, None));
        LiveRunRegistry::clear();
    }

    #[test]
    fn hidden_cancelled_terminal_generation_unblocks_identical_retry() {
        let _registry = lock_live_registry_for_test();
        let session = format!("hidden-terminal-retry-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let (handle, _command_rx_guard) = connected_dummy_handle("hidden-terminal-generation");
        handle.set_request_fingerprint(91);
        handle.cancel_requested.store(true, Ordering::Release);
        store_terminal_error(&handle.terminal_error, "Cursor live run cancelled");
        handle.completed.store(true, Ordering::Release);
        LiveRunRegistry::reserve(&session)
            .expect("reserve hidden generation")
            .insert(Arc::clone(&handle))
            .expect("insert hidden terminal generation");

        assert!(
            LiveRunRegistry::get_run(&session, None).is_none(),
            "cancelled terminal handles are intentionally hidden from attach"
        );
        assert!(matches!(
            LiveRunRegistry::probe_run(&session, None),
            LiveRunProbe::Free
        ));
        assert!(
            LiveRunRegistry::running_generation(&session, None).is_none(),
            "probing a definitive cancellation must remove the hidden generation"
        );
        let LiveSlotClaim::Reserved(reservation) =
            LiveRunRegistry::try_claim_run_for_operation(&session, None, 91)
        else {
            panic!("identical retry must be admitted after definitive cancellation");
        };
        reservation.release();
        LiveRunRegistry::clear();
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)]
    async fn identical_retry_resumes_from_succeeded_replay_tombstone() {
        let _registry = lock_live_registry_for_test();
        let session = format!("succeeded-replay-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let body: crate::anthropic::schema::MessagesRequest =
            serde_json::from_value(serde_json::json!({
                "model": "cursor-grok-4.6-xhigh-fast",
                "stream": true,
                "messages": [{"role": "user", "content": "what is 2+2?"}]
            }))
            .unwrap();
        let fingerprint = live_request_fingerprint(
            &super::super::live_operation_fingerprint_payload(&body, None),
        );
        let handle = dummy_handle("replayable-generation");
        handle.set_request_fingerprint(fingerprint);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(handle)
            .expect("insert");
        LiveRunRegistry::seal_success_if(
            &session,
            "replayable-generation",
            Some(Arc::new(vec![
                LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text: "4".into() }),
                LiveRunEvent::Cursor(CursorStreamEvent::End),
            ])),
        );

        let outcome = super::super::await_live_run_resume(
            &session,
            None,
            &body,
            "msg_replay".into(),
            "cursor-grok-4.6-xhigh-fast".into(),
            1,
            None,
            true,
        )
        .await;
        let super::super::LiveResumeOutcome::Resumed(mut events) = outcome else {
            panic!("identical retry must resume from the retained response");
        };
        assert!(matches!(
            events.recv().await,
            Some(Ok(LiveRunEvent::Cursor(CursorStreamEvent::TextDelta { text }))) if text == "4"
        ));
        assert!(matches!(
            events.recv().await,
            Some(Ok(LiveRunEvent::Cursor(CursorStreamEvent::End)))
        ));
        assert!(
            events.recv().await.is_none(),
            "replayed response must terminate cleanly"
        );

        // The tombstone stays for further duplicates within the TTL, and a
        // NEW request (different fingerprint) releases it as before.
        assert!(
            LiveRunRegistry::completed_replay_for(&session, None, fingerprint).is_some(),
            "replay tombstone must survive one duplicate delivery"
        );
        LiveRunRegistry::release_success_if_new_request(&session, None, fingerprint ^ 1);
        assert!(
            !LiveRunRegistry::is_occupied_run(&session, None),
            "a new operation must release the tombstone"
        );
        LiveRunRegistry::clear();
    }

    #[test]
    fn succeeded_claims_map_by_fingerprint_without_false_ambiguity() {
        let _registry = lock_live_registry_for_test();
        let session = format!("succeeded-claims-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();

        // No replay retained (overflow / no recorded End).
        let handle = dummy_handle("no-replay-generation");
        handle.set_request_fingerprint(7);
        LiveRunRegistry::reserve(&session)
            .expect("reserve")
            .insert(handle)
            .expect("insert");
        LiveRunRegistry::seal_success_if(&session, "no-replay-generation", None);

        // Identical duplicate: completed turns are never ambiguous — busy.
        assert!(matches!(
            LiveRunRegistry::try_claim_run_for_operation(&session, None, 7),
            LiveSlotClaim::CompletedNoReplay
        ));
        // Fingerprint-less callers keep the conservative classification.
        assert!(matches!(
            LiveRunRegistry::try_claim_run(&session, None),
            LiveSlotClaim::Ambiguous
        ));
        // A NEW operation releases the tombstone and claims the slot even on
        // paths that skip the handle_messages release preamble.
        let LiveSlotClaim::Reserved(reservation) =
            LiveRunRegistry::try_claim_run_for_operation(&session, None, 8)
        else {
            panic!("a new operation must release the Succeeded tombstone");
        };
        reservation.release();
        assert!(!LiveRunRegistry::is_occupied_run(&session, None));
        LiveRunRegistry::clear();
    }

    #[test]
    fn ambiguous_tombstone_only_blocks_the_same_operation() {
        let _registry = lock_live_registry_for_test();
        let session = format!("ambiguous-fp-{}", uuid::Uuid::new_v4());
        LiveRunRegistry::clear();
        let mut reservation = LiveRunRegistry::reserve(&session).expect("reserve");
        reservation.set_operation_fingerprint(11);
        reservation.seal_ambiguous(Instant::now() + Duration::from_secs(60));

        assert!(
            LiveRunRegistry::is_ambiguous_for_operation(&session, None, 11),
            "the sealed operation must stay fail-closed"
        );
        assert!(
            !LiveRunRegistry::is_ambiguous_for_operation(&session, None, 22),
            "a later grok-build stage / next turn must not inherit that 409"
        );
        assert!(matches!(
            LiveRunRegistry::try_claim_run_for_operation(&session, None, 11),
            LiveSlotClaim::Ambiguous
        ));

        let LiveSlotClaim::Reserved(reservation) =
            LiveRunRegistry::try_claim_run_for_operation(&session, None, 22)
        else {
            panic!("a new operation must not inherit another turn's ambiguous 409");
        };
        reservation.release();
        assert!(!LiveRunRegistry::is_occupied_run(&session, None));
        LiveRunRegistry::clear();
    }

    #[tokio::test]
    async fn attach_replay_rejects_fingerprint_mismatch() {
        let mut harness = spawn_attach_replay_driver("attach-wrong-op");
        send_text_delta(&harness.upstream_tx, "belongs to another operation").await;
        let _first = tokio::time::timeout(Duration::from_secs(2), harness.event_rx.recv())
            .await
            .expect("text delta flushed")
            .expect("stream open")
            .expect("no error");
        drop(harness.event_rx);

        let (ack, ready) = oneshot::channel();
        harness
            .command_tx
            .send(RunCommand::AttachReplay {
                ack,
                expected_fingerprint: 7,
                fingerprint_source: Arc::new(AtomicU64::new(8)),
            })
            .await
            .expect("driver accepts commands");
        let error = tokio::time::timeout(Duration::from_secs(2), ready)
            .await
            .expect("driver answers attach")
            .expect("attach ack not dropped")
            .expect_err("a different operation must not receive this segment");
        assert_eq!(error.status, 503);
    }
